function placeSearchForm(){return `<section class="place-map-picker"><form id="place-search-form" class="place-map-search"><label class="sr-only" for="map-place-query">Place name or region</label><input id="map-place-query" name="query" required minlength="2" maxlength="120" value="${esc(placePickerQuery)}" placeholder="Search attractions, food or stays"><button type="submit" class="btn small">검색</button><input type="hidden" name="provider" value="google"></form><div class="place-picker-map" data-place-picker-map role="region" aria-label="Google Map for choosing a place"></div><section class="place-picker-sheet"><div class="trip-sheet-handle" aria-hidden="true"></div><div class="place-picker-tabs"><button type="button" data-action="place-picker-tab" data-id="search" aria-pressed="${placePickerTab==='search'}">Search results</button><button type="button" data-action="place-picker-tab" data-id="saved" aria-pressed="${placePickerTab==='saved'}">Saved places</button></div><p id="place-search-status" role="status">${esc(placePickerStatus)}</p><div id="place-picker-detail" aria-live="polite"></div><div id="place-search-results"></div></section></section>`;}
function renderPickerResults(){const host=$('#place-search-results');if(!host)return;const places=pickerPlaces();host.innerHTML=places.map((p,i)=>`<article class="place-map-row ${p.id===placePickerSelected?'is-selected':''}"><span class="place-map-row-photo">${placeArt(p)}</span><button type="button" class="place-map-row-select" data-action="preview-api-place" data-id="${i}" aria-pressed="${p.id===placePickerSelected}" ><strong>${i+1}. ${esc(p.name)}</strong><span>${esc(p.address)}</span><small>${pinEligible(p)?'View location on map':'Tap to view place'}</small></button></article>`).join('')||`<div class="place-picker-empty">${placePickerTab==='saved'?'Saved places가 없어요.':'Search to see places on the map and in the list.'}</div>`;}
function mountPlacePicker(){renderPickerResults();const places=pickerPlaces();window.ReelGoogleMap.mount($('[data-place-picker-map]'),places.map(p=>pinEligible(p)?p:{...p,lat:null,lng:null}),placePickerSelected,id=>{const index=pickerPlaces().findIndex(p=>p.id===id);previewAPIPlace(index);});}
async function searchPlaces(form,d){window.ReelEnablePlaceSearch?.();const version=++placeSearchVersion,button=form.querySelector('button'),status=$('#place-search-status');placeSelectionVersion++;pendingAPIPlace=null;placePickerSelected='';placePickerQuery=d.query;placePickerTab='search';button.disabled=true;status.textContent='Finding places…';placeSearchResults=[];$('#place-picker-detail').innerHTML='';mountPlacePicker();
 try{const found=await window.ReelPlaceAPI.search(d.query,'google');if(version!==placeSearchVersion||!form.isConnected)return;placeSearchResults=found;placePickerStatus=found.length?'Select a result or pin to check its location.':'No results found. Leave an inquiry about the place you are looking for.';}
 catch(error){if(version!==placeSearchVersion||!form.isConnected)return;placePickerStatus='Search results could not load. Try again or leave an inquiry.';}finally{button.disabled=false;}
 if(version!==placeSearchVersion||!form.isConnected)return;status.textContent=placePickerStatus;if(!placeSearchResults.length){const link=document.createElement('a');link.href='#support?placeQuery='+encodeURIComponent(placePickerQuery);link.className='btn secondary small';link.textContent='Leave an inquiry';status.append(document.createElement('br'),link);}document.querySelectorAll('[data-action="place-picker-tab"]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===placePickerTab)));mountPlacePicker();}
async function previewAPIPlace(index){const record=pickerPlaces()[index],version=++placeSelectionVersion,route=location.hash;if(!record)return;pendingAPIPlace=null;placePickerSelected=record.id;const host=$('#place-picker-detail');host.innerHTML='<p role="status">Checking this place…</p>';mountPlacePicker();
 if(!pinEligible(record)){host.innerHTML=`<article class="place-pin-confirm"><div class="place-pin-photo">${placeArt(record)}</div><div><h3>${esc(record.name)}</h3><p>${esc(record.address)}</p><small>${esc(record.type)}</small></div></article>`;return;}
 try{const p=await window.ReelPlaceAPI.details(record);if(version!==placeSelectionVersion||location.hash!==route||!host.isConnected)return;if(!pinEligible(p))throw new Error('coordinates');pendingAPIPlace=p;host.innerHTML=`<article class="place-pin-confirm"><div class="place-pin-photo">${placeArt(p)}</div><div><small>Selected place</small><h3>${esc(p.name)}</h3><p>${esc(p.address)}</p>${(p.photoAuthors||[]).concat(p.attributions||[]).map(a=>`<small><a href="${esc(window.ReelPlaceAPI.safeURL(a.url))}" target="_blank" rel="noopener noreferrer">${esc(a.name)}</a></small>`).join('')}</div><button type="button" class="btn" data-action="save-api-place">${addingToTrip()?'Add this place to the itinerary':'Save this place'}</button></article>`;host.scrollIntoView?.({behavior:'smooth',block:'nearest'});}
 catch{if(version===placeSelectionVersion&&host.isConnected)host.innerHTML='<p role="alert">Could not load this place. Please select it again.</p>';}}
function saveAPIPlace(){const p=pendingAPIPlace;if(!p||!pinEligible(p))return;const trip=addingToTrip();if(trip&&state.board.length>=20&&!state.board.includes(p.id)){toast('Day에 20 places까지 담을 수 있어요.');return;}const resolved=resolvingPlace(),existing=place(resolved)||state.places.find(x=>x.source===p.source&&x.placeId===p.placeId)||place(p.id);if(existing)p.id=existing.id;if(existing){delete existing.demoCoordinates;delete existing.locationNote;delete existing.original;Object.assign(existing,{...p,duration:existing.duration});}else state.places.push(p);if(!libraryIds().includes(p.id))state.library.push(p.id);if(trip&&!state.board.includes(p.id)){state.board.push(p.id);state.saved=false;}pendingAPIPlace=null;save();$('#dialog').close();go(trip?tripDetailRoute():'board');}

function reviewMapMode(){return window.REEL_MAPS_CONFIG?.mode==='review'||!window.REEL_MAPS_CONFIG?.apiKey;}
function reviewPosition(p){
 if(p.source||!window.ReelGoogleMap.valid(p))return null;
 const scale=256*Math.pow(2,16),merc=lat=>Math.log(Math.tan(Math.PI/4+lat*Math.PI/360));
 const x=320+(p.lng-127.044)/360*scale,y=300-(merc(p.lat)-merc(37.5446))/(2*Math.PI)*scale-110;
 return x>25&&x<615&&y>25&&y<420?{x:x/640*100,y:y/490*100}:null;
}
function reviewVisitLines(places){
 const points=places.map(p=>{const pos=reviewPosition(p);return pos?{x:pos.x*6.4,y:Math.max(14,pos.y)*4.9}:null;});
 const segments=points.slice(1).flatMap((to,i)=>{const from=points[i];if(!from||!to)return [];const path=`${from.x},${from.y} ${(from.x+to.x)/2},${(from.y+to.y)/2} ${to.x},${to.y}`;return [`<g data-visit-segment="${esc(places[i].id)}:${esc(places[i+1].id)}"><polyline points="${path}" class="visit-line-halo"/><polyline points="${path}" class="visit-line" marker-mid="url(#visit-arrow)"/></g>`];});
 return `<svg class="review-visit-lines" viewBox="0 0 640 490" aria-label="Lines showing the order of your stops" role="img"><defs><marker id="visit-arrow" markerWidth="8" markerHeight="8" refX="4" refY="4" orient="auto" markerUnits="strokeWidth"><path d="M1 1L7 4L1 7Z" fill="#7353c7"/></marker></defs>${segments.join('')}</svg>`;
}
function reviewMapImage(places,active,showRoute=true){return `<div class="review-map-image" role="group" aria-label="Photo pins on a Google Maps screenshot"><img class="review-map-background" src="../assets/photos/google-seongsu-review.png" width="640" height="600" alt="Google Maps screenshot of Seoul Forest and Seongsu. Map data ©2026 TMap Mobility. This image cannot be panned or zoomed.">${showRoute?reviewVisitLines(places):''}${places.map((p,i)=>{const pos=reviewPosition(p);return pos?`<button class="review-photo-pin ${p.id===active?'active':''}" style="left:${pos.x}%;top:${Math.max(14,pos.y)}%" data-action="focus-place" data-id="${p.id}" aria-label="On the map: ${esc(p.name)} select" aria-pressed="${p.id===active}">${placeArt(p).replace('loading="lazy"','loading="eager"')}<b>${i+1}</b></button>`:'';}).join('')}</div><div class="review-map-attribution">Google Maps · Map data ©2026 TMap Mobility</div>`;}
let mapPlaces=[];
function mapPanel(ids=state.board,snapshots=null,discovery=false){
 mapPlaces=snapshots?snapshots.map(p=>({...p})):ids.map(place).filter(Boolean).map(p=>{const seed=window.REEL_PLACES.find(x=>x.id===p.id);return p.original?p:{...seed,...p};});
 const visible=mapPlaces.filter(p=>reviewMapMode()?reviewPosition(p):pinEligible(p)),active=visible.find(p=>p.id===state.focus)||visible[0];
 return `<section class="map-workspace" aria-label="Google map and selected places">${reviewMapMode()?reviewMapImage(mapPlaces,active?.id,!discovery):'<div class="google-map-host" data-google-map role="region" aria-label="Google place map"></div>'}${active&&!discovery?`<div class="map-selected"><div class="map-photo">${placeArt(active)}</div><div><strong>${esc(active.name)}</strong><p>${esc(active.demoCoordinates?'Please verify the exact location.':active.locationNote||active.area+' · '+active.type)}</p><a target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(active.lat+','+active.lng)}">Open in Google Maps ↗</a></div></div>`:''}</section>`;
}
function mountMaps(){if(current()==='manual'&&!isGuest()){mountPlacePicker();const query=new URLSearchParams(location.hash.split('?')[1]||'').get('query');if(query&&discoveryRoute!==location.hash){discoveryRoute=location.hash;placePickerQuery=query;const form=$('#place-search-form');form.elements.query.value=query;searchPlaces(form,{query});}return;}const h=document.querySelector('[data-google-map]');window.ReelGoogleMap.mount(h,mapPlaces.map(p=>pinEligible(p)?p:{...p,lat:null,lng:null}),state.focus||mapPlaces.find(pinEligible)?.id,id=>{if(current()==='guide-quote'){updateQuoteMap(null,id);return;}state.focus=id;save();render();});}
