 const shortTitleOriginal=({trips:'Trip details',board:'Saved places',processing:'Find places',results:isGuest()?'Start with Reeltrip':'Check places',manual:'Add places',planner:'Edit itinerary',guide:'Meet your mate',request:location.hash.includes('mode=free')?'Request a custom quote':'Request a mate for my trip',requested:'Request status',quote:'Trip proposal',checkout:'View booking',booking:'Booking details',chat:'Chats',cancel:'Cancel booking',review:'Write a review',upcoming:'Upcoming trips',settings:'Settings',support:'Help',policies:policySection()==='privacy'?'Privacy Policy':policySection()==='terms'?'Terms of Service':'Service information','guide-fee':'Matching fee','guide-quote':'Create a proposal'})[r]||screen?.name||'Reeltrip';
