let notificationFilter='all';
function notifications(){const items=notificationItems(),visible=items;return `<section class="notifications-page">${visible.length?`<div class="notification-list">${visible.map(n=>`<a class="notification-item ${n.read?'is-read':'is-unread'}" href="#${n.route}" data-action="notification-open" data-id="${esc(n.id)}"><div><strong>${!n.read?'<span class="notification-unread-mark" aria-hidden="true"></span><span class="sr-only">Unread notifications · </span>':''}${esc(n.title)}</strong><p>${esc(n.body)}</p>${n.time?`<time datetime="${new Date(n.time).toISOString()}">${new Date(n.time).toLocaleDateString(document.documentElement.lang==='en'?'en-US':'ko-KR',{timeZone:'Asia/Seoul',month:'short',day:'numeric'})}</time>`:''}</div><span class="notification-chevron" aria-hidden="true">${icon('chevronRight')}</span></a>`).join('')}</div>`:`<div class="notification-empty rt-empty-card rt-empty-plain"><span class="rt-empty-card-icon">${icon('bell')}</span><h2>No notifications yet</h2><p>New updates will appear here.</p></div>`}</section>`;}

function saveRestaurant(id){
  const item=window.ReelRestaurants.find(restaurant=>restaurant.id===id);
  if(!item)return false;
  if(!place(id))state.places.push({id,restaurant:true,name:item.name[0],ko:item.name[0],address:item.address,type:'Food',duration:45,recommended:true});
  resolvePlace(id);
  return true;
}
function resumeSignupAction(){
 if(pendingRecommendation){const record=pendingRecommendation;pendingRecommendation=null;saveRecommendation(record);go('home');return true;}
 if(pendingRequestRoute){const route=pendingRequestRoute;pendingRequestRoute=null;go(route);return true;}
 if(pendingEstimate){pendingEstimate=false;go(activeMateStep()?.route||'request?sample=1');return true;}
 if(!pendingRestaurant)return false;
 const id=pendingRestaurant;pendingRestaurant=null;
 if(!saveRestaurant(id))return false;
 return true;
}
let recommendationQuery='Seoul tourist attractions',recommendationRows=[],recommendationStatus='idle',recommendationVersion=0,pendingRecommendation=null;
function recommendationSaved(p){return !isGuest()&&state.places.some(x=>x.source==='google'&&x.placeId===p.placeId&&libraryIds().includes(x.id));}
function recommendationCards(){
 if(recommendationStatus==='loading'||recommendationStatus==='idle')return '<div class="recommendation-loading" role="status">Loading places and photos…</div>';
 if(recommendationStatus==='error')return '<div class="recommendation-empty" role="status"><p>Could not load places.</p><button class="btn secondary small" data-action="recommendation-retry">Try again</button></div>';
 if(!recommendationRows.length)return '<p class="recommendation-empty">No places found. Try another region or place.</p>';
 return `<div class="recommendation-grid">${recommendationRows.map((p,i)=>{const saved=recommendationSaved(p);return `<article class="recommendation-card"><div class="recommendation-photo">${window.ReelPlaceAPI.safeURL(p.photoURL)?`<span class="provider-photo"><img class="travel-photo" src="${esc(window.ReelPlaceAPI.safeURL(p.photoURL))}" alt="${esc(p.name)}" loading="lazy" decoding="async" referrerpolicy="strict-origin-when-cross-origin"></span>`:art()}</div><div class="recommendation-body"><h3>${esc(p.name)}</h3><p>${esc(p.address)}</p><div class="recommendation-attribution">${(p.photoAuthors||[]).concat(p.attributions||[]).map(a=>a.url?`<a href="${esc(window.ReelPlaceAPI.safeURL(a.url))}" target="_blank" rel="noopener noreferrer">${esc(a.name)}</a>`:esc(a.name)).join(' · ')}</div><div class="recommendation-actions">${p.googleMapsURI?`<a href="${esc(p.googleMapsURI)}" target="_blank" rel="noopener noreferrer">Map ↗</a>`:''}<button type="button" class="btn small" data-action="save-recommendation" data-id="${i}" ${saved?'disabled':''} aria-label="${esc(p.name)} ${saved?'Saved':'Save'}">${icon(saved?'check':'plus',20)}${saved?'Saved':'Save'}</button></div></div></article>`;}).join('')}</div>`;
}
function paintRecommendations(){const host=$('#recommendation-results');if(!host)return;host.innerHTML=interfaceMarkup(recommendationCards());host.setAttribute('aria-busy',String(recommendationStatus==='loading'));const label=$('#recommendation-query');if(label)label.textContent=recommendationQuery;document.querySelectorAll('[data-action="discover-query"]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.query===recommendationQuery)));}
async function loadRecommendations(query=recommendationQuery,force=false){if(!force&&query===recommendationQuery&&recommendationStatus!=='idle'){paintRecommendations();return;}recommendationQuery=query;const version=++recommendationVersion;recommendationStatus='loading';recommendationRows=[];paintRecommendations();try{const rows=await window.ReelPlaceAPI.search(query,'google');if(version!==recommendationVersion)return;recommendationRows=rows.filter(pinEligible).slice(0,6);recommendationStatus='ready';}catch{if(version!==recommendationVersion)return;recommendationStatus='error';}paintRecommendations();}
function saveRecommendation(record){if(!record||!pinEligible(record))return false;if(isGuest()){pendingRecommendation={...record};go('member-required');return false;}const existing=state.places.find(p=>p.source==='google'&&p.placeId===record.placeId);const p=existing||{...record};if(!existing)state.places.push(p);else Object.assign(p,{...record,id:existing.id,duration:existing.duration||45});if(!libraryIds().includes(p.id))state.library.push(p.id);save();paintRecommendations();const next=$('#discover-next-step');if(next)next.innerHTML=interfaceMarkup(discoveryNext());toast('Added to saved places.');return true;}
let discoveryRoute='';
function startDiscovery(query){query=String(query||'').trim();if(query.length<2||query.length>120)return;loadRecommendations(query,true);}
function discoveryNext(){
 const count=isGuest()?0:libraryIds().length;
 if(!count)return '';
 return `<div class="discover-next"><div><strong>${signupText('savedTripTitle')}</strong><p>${esc(signupText('savedTripHint').replace('{count}',String(count)))}</p></div><div class="discover-next-links">${action(signupText('createTripFromSaved'),'new-trip','secondary small')}</div></div>`;
}
function discoveryPlaces(){
 return `<section class="mate-intro" aria-labelledby="mate-intro-title"><header><span class="mate-intro-eyebrow">Korea, your way</span><h2 id="mate-intro-title">New to Korea?<br>Make the trip your own.</h2><p>Skip the package. Set your own itinerary.<br>Explore with a mate who knows Korea.</p></header><figure class="rt-editorial-hero"><img src="../assets/photos/local-mate-walk-v1.png" alt="Travel artwork of travelers exploring a Korean neighborhood with a local mate" width="1536" height="1024" loading="lazy" decoding="async"><figcaption><span>LOCAL MOMENTS</span><strong>Discover the Korea you might have missed.</strong></figcaption></figure><div class="mate-intro-list"><article class="card rt-editorial-card"><div class="rt-editorial-card-photo"><img class="travel-photo" src="../assets/photos/mate-benefit-places-graphic-v1.png" alt="A map and pin illustrating personalized place selection" width="1086" height="1448" loading="lazy" decoding="async"></div><div class="rt-editorial-card-copy"><span class="rt-editorial-number">01 / YOUR PLACES</span><h3>Your places</h3><p>That street from a video. Your favorite cafe. Your kind of places.</p></div></article><article class="card rt-editorial-card"><div class="rt-editorial-card-photo"><img class="travel-photo" src="../assets/photos/mate-benefit-time-graphic-v1.png" alt="A clock and calendar illustrating flexible travel time" width="1086" height="1448" loading="lazy" decoding="async"></div><div class="rt-editorial-card-copy"><span class="rt-editorial-number">02 / YOUR PACE</span><h3>Your schedule</h3><p>Explore on your schedule, with help speaking Korean and getting around.</p></div></article><article class="card rt-editorial-card"><div class="rt-editorial-card-photo"><img class="travel-photo" src="../assets/photos/mate-benefit-budget-graphic-v1.png" alt="Mate proposal cards and coins illustrating budget comparison" width="1086" height="1448" loading="lazy" decoding="async"></div><div class="rt-editorial-card-copy"><span class="rt-editorial-number">03 / YOUR CHOICE</span><h3>Your budget</h3><p>Compare plans and prices. Choose your mate.</p></div></article></div><footer class="rt-card-actions-centered"><strong>What does your Korea trip look like?</strong><p>Get proposals for your trip and choose a mate to join you.</p>${action('Find a travel mate','home-mate-start')}<span class="mate-intro-note">Check what is included and the cost in each proposal.</span></footer></section>`;
}

function activeMateStep(){
 if(state.booking&&!['cancelled','completed'].includes(state.booking.status))return {route:'booking',label:signupText('trackBooking')};
 if(state.request?.status==='quoted')return {route:'requested',label:signupText('compareOffers')};
 if(state.request?.status==='requested')return {route:'requested',label:signupText('trackRequest')};
 return null;
}
function mateNextButton(kind='secondary'){
 const next=activeMateStep();
 return next?btn(next.label,next.route,kind):btn(signupText('mateRequestPublic'),'request',kind);
}
function requestStops(){stashDay();return [...new Set(state.days.flatMap(d=>d.ids))].filter(id=>place(id));}
function home(){return `<section class="import-card action-import"><div class="import-heading"><span class="import-icon">${icon('link')}</span><div><h1>From your feed,<br>to your trip!</h1><p class="import-subtext">Your next trip starts with a video link.</p></div></div><form id="extract-form"><label class="sr-only" for="video-url">YouTube Shorts or Instagram Reels link</label><div class="import-input-row"><input id="video-url" type="url" inputmode="url" autocomplete="off" autocapitalize="none" spellcheck="false" aria-describedby="url-error" placeholder="Enter your link!" maxlength="2048"><button class="import-search btn light small" type="submit">Check link</button></div><p id="url-error" class="error" role="alert"></p></form></section>${discoveryPlaces()}`;}
function processing(){const fail=state.extraction==='failed';return `<section class="centerbox card pad extraction-card ${fail?'is-failed':''}" aria-labelledby="extraction-title"><div class="extraction-visual" aria-hidden="true">${icon(fail?'warning':'location',48)}</div><div class="eyebrow">Find places in the video</div><h1 id="extraction-title">${fail?'We could not open this video.':'Looking for the places in your video…'}</h1>${fail?'':`<div class="extraction-progress" aria-hidden="true"><span></span></div><ol class="extraction-stages"><li class="is-complete"><span class="extraction-stage-icon" aria-hidden="true">${icon('check',20)}</span><span>Link format checked</span></li><li class="is-active" aria-current="step"><span class="extraction-stage-icon" aria-hidden="true"></span><span>Finding places in the video</span></li><li class="is-pending"><span class="extraction-stage-icon" aria-hidden="true">3</span><span>Check place names and branches</span></li></ol>`}<p class="extraction-note">${fail?'The video may be private or deleted. Try a public link, or add a place using its name and address.':'Places with the same name may have different branches. Check the address in the results.'}</p><div class="buttons extraction-actions">${fail?`${btn('Search places','manual')}${btn('Try another link','home','secondary')}`:`${btn('Go back','home','secondary small')}`}</div></section>`;}
function placeCard(p,mode='result',number=null){const saved=googleRegistered(p)&&libraryIds().includes(p.id);if(mode==='result')return `<article class="card rt-place-card ${state.focus===p.id?'is-focused':''}"><div class="rt-place-card-photo">${placeArt(p)}</div><div class="rt-place-card-body"><h3><button type="button" class="rt-place-select" data-action="focus-place" data-id="${esc(p.id)}" aria-pressed="${state.focus===p.id}" aria-label="On the map: ${esc(p.name)} view">${number===null?'':`<span class="rt-place-number">${number}</span>`}${esc(p.name)}</button></h3><p>${esc(p.type)}</p><p>${esc(p.address)}</p>${googleRegistered(p)?'<span class="badge">Google Maps</span>':''}</div><button type="button" class="iconbtn rt-save-action" data-action="save-result-place" data-id="${esc(p.id)}" aria-label="${esc(p.name)} · ${saved?'Saved':'Save place'}" title="${saved?'Saved':'Save place'}" ${saved?'disabled':''}>${icon(saved?'check':'board',20)}</button></article>`;return `<article class="place"><div class="place-thumb">${placeArt(p)}</div><div class="place-main"><h3>${esc(p.name)}</h3><p>${esc(p.type)}${p.area&&p.area!==p.address?' · '+esc(p.area):''}</p>${googleRegistered(p)?'<span class="badge">Google Maps</span>':''}<p>${esc(p.address)}</p>${mode==='result'?`<button type="button" class="btn secondary small" data-action="save-result-place" data-id="${esc(p.id)}" aria-label="${esc(p.name)} · ${saved?'Saved':'Save place'}" ${saved?'disabled':''}>${saved?'Saved':'Save place'}</button>`:`<details class="place-menu"><summary aria-label="${esc(p.name)} · Manage this place"><span aria-hidden="true">${icon('more')}</span></summary><div class="place-menu-panel rt-action-menu"><div class="rt-action-menu-list"><button class="rt-action-menu-item" data-action="must" data-id="${p.id}" aria-pressed="${state.must.includes(p.id)}">${icon('star',20)}<span>${state.must.includes(p.id)?'Must-visit':'Mark as must-visit'}</span></button><button class="rt-action-menu-item rt-action-menu-item--danger" data-action="remove" data-id="${p.id}">${icon('trash',20)}<span>Remove</span></button></div></div></details>`}</div></article>`;}
function results(){const filtered=state.places.filter(p=>!p.recommended);return `${state.source.startsWith('https:')?`<a class="rt-source-link" href="${esc(state.source)}" target="_blank" rel="noopener noreferrer" aria-label="View original video · ${esc(state.source)}" title="${esc(state.source)}">${icon('link',20)}<span><small>Original video</small><span class="rt-source-link-url">${esc(state.source)}</span></span>${icon('external',18)}</a>`:''}${filtered.length?`<div class="sectionhead"><h2>${filtered.length} ${filtered.length===1?"place":"places"} found</h2></div>`:''}<div class="rt-map-browser">${filtered.length?mapPanel([],filtered,true):''}<section class="rt-map-browser-list" aria-label="Places found:">${filtered.map((p,i)=>placeCard(p,'result',i+1)).join('')||`<section class="card pad rt-empty-card"><span class="rt-empty-card-icon">${icon('search',28)}</span><h2>No places found.</h2><p>Try searching with another video link.</p></section>`}</section></div><div class="rt-page-action">${filtered.length?`<a class="btn" href="#board"><span>View saved places</span>${icon('arrowRight',20)}</a>`:`<button type="button" class="btn" data-action="board-video"><span>Search again</span>${icon('search',20)}</button>`}</div>`;}
function addingToTrip(){return new URLSearchParams(location.hash.split('?')[1]||'').get('from')==='trips';}
function placeSuggestion(){
 return `<details class="trip-settings"><summary>Suggest a place</summary><form class="card pad" id="suggest-place-form"><label>Place name<input name="name" required maxlength="80"></label><label>Address or neighborhood<input name="address" required maxlength="160"></label><button class="btn secondary" type="submit">Save suggestion</button></form></details>`;
}
function manual(){return `<div class="place-picker-page">${placeSearchForm()}</div>`;}
function startVideoSearch(url){previewExtractionStarted=true;state.source=url;state.extraction='processing';state.filter='All';save();go('processing');}
function boardVideoDialog(){modal(`<div class="trip-menu-heading"><h2>Paste your video link</h2><button type="button" class="textbtn" data-action="close" aria-label="Close">${icon('close')}</button></div><form id="board-video-form"><label for="board-video-url">YouTube Shorts or Instagram Reels link</label><input id="board-video-url" name="url" type="url" required maxlength="2048" placeholder="Enter your link!" autocomplete="off"><p id="board-video-error" class="error" role="alert"></p><div class="board-video-actions"><button type="submit" class="btn">Check places</button></div></form>`,'board-video');}
let libraryFilter='all';
function boardAddMenu(){modal(`<div class="trip-menu-heading"><h2>Save a place</h2><button type="button" class="textbtn" data-action="close" aria-label="Close">${icon('close')}</button></div><div class="library-add-options"><button type="button" class="trip-add-option" data-action="board-video">${icon('link')}<span><strong>Save from a video link</strong><small>Find places from a video you love.</small></span></button><button type="button" class="trip-add-option" data-action="board-search">${icon('board')}<span><strong>Search for a place</strong><small>Find somewhere by name or address.</small></span></button></div>`,'trip-menu');}
function board(){
 const places=libraryIds().map(place).filter(googleRegistered),visible=places.filter(p=>libraryFilter==='all'||state.must.includes(p.id));
 return `<section class="saved-library"><div class="library-heading"><h1>My places <span>${places.length}</span></h1></div>${!places.length?`<div class="card rt-empty-card"><span class="rt-empty-card-icon" aria-hidden="true">${icon('board')}</span><h2>Save places you want to visit</h2><p>Places from videos or searches,<br>saved here, ready for your next trip.</p>${action('Save a place','board-add')}</div>`:`<div class="chips library-filters" role="group" aria-label="Filter saved places">${[['all','All'],['must','Must-visit']].map(([key,label])=>chip(label,libraryFilter===key,`data-action="library-filter" data-id="${key}" aria-pressed="${libraryFilter===key}"`)).join('')}</div><div class="library-list">${visible.map(p=>`<div class="library-place">${placeCard(p,'board')}</div>`).join('')||'<div class="library-filter-empty"><p>Pick the places you most want to visit.</p><p class="hint">Mark your favorites in each place’s ⋯ menu.</p></div>'}</div><section class="library-trip-footer"><h2>Ready to plan a trip with your saved places?</h2><p>Choose a trip and add the places you want to visit.</p><div class="buttons">${action('Create a new trip','new-trip','small')}${btn('View my trips','trips','light small')}</div></section>`}</section>`;
}

function timeline(ids=state.board,edit=false){return `<div class="timeline">${ids.map(place).filter(Boolean).map((p,i)=>{return `<article class="stop"><div class="stop-dot">${i+1}</div><div class="stop-card"><div class="timeline-cover">${placeArt(p)}<span>Seoul · ${esc(p.area)}</span></div><h3>${esc(p.name)} ${state.must.includes(p.id)?'<span class="badge">Must-visit</span>':''}</h3><p>${esc(p.type)}${i?' · Check travel time':''}</p>${edit?`<div class="stop-controls"><button class="iconbtn" aria-label="${esc(p.name)} Move up" data-action="move" data-id="${p.id}" data-dir="-1" ${i===0?'disabled':''}>${icon('arrowUp')}</button><button class="iconbtn" aria-label="${esc(p.name)} Move down" data-action="move" data-id="${p.id}" data-dir="1" ${i===ids.length-1?'disabled':''}>${icon('arrowDown')}</button></div>`:''}</div></article>`;}).join('')}</div>`;}
// Coordinate-only estimate, not a road route or live travel time. Walking speed: 4 km/h.
function walkingEstimate(a,b){
 const valid=p=>p&&Number.isFinite(p.lat)&&Number.isFinite(p.lng)&&Math.abs(p.lat)<=90&&Math.abs(p.lng)<=180;
 if(!valid(a)||!valid(b)||(window.REEL_MAPS_CONFIG?.apiKey&&(!pinEligible(a)||!pinEligible(b))))return null;
 const rad=n=>n*Math.PI/180,dl=rad(b.lat-a.lat),dn=rad(b.lng-a.lng);
 const h=Math.sin(dl/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dn/2)**2;
 const meters=6371000*2*Math.asin(Math.sqrt(Math.min(1,Math.max(0,h))));
 return {meters,minutes:meters===0?0:Math.max(1,Math.ceil(meters/(4000/60)))};
}
function travelLeg(a,b){const e=walkingEstimate(a,b);if(!e)return '<div class="route-leg"><strong>Location needed</strong><small>Travel time needs coordinates for both stops.</small></div>';
 const directions='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(a.lat+','+a.lng)+'&destination='+encodeURIComponent(b.lat+','+b.lng);
 const distance=e.meters<1000?Math.round(e.meters)+' m':(e.meters/1000).toFixed(1)+' km';
 return `<div class="route-leg"><strong>About ${e.minutes} min on foot <span>· ${distance} straight-line</span></strong><a class="route-directions" href="${esc(directions)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(a.name)} → ${esc(b.name)} · Directions in Google Maps">Directions ↗</a><small>${a.demoCoordinates||b.demoCoordinates?'Estimate based on location':'Estimated walk · Actual route may differ.'}</small></div>`;
}
function planner(){return tripDetail();} // Compatibility for the retired B-06 screen.
function tripOverview(){stashDay();return `<section class="trip-overview"><div class="sectionhead"><div><span class="eyebrow">Whole trip · Korea time (KST)</span><h2>${esc(state.title)}</h2></div><span class="badge">${state.days.length} ${state.days.length===1?"day":"days"}</span></div>${state.days.map((d,i)=>`<article class="overview-day"><div class="overview-head"><strong>Day ${i+1} · ${esc(d.date)}</strong><button class="textbtn" data-action="overview-day" data-value="${i}">Open day →</button></div><div class="overview-stats"><div><span>Stops</span><strong>${d.ids.length}</strong></div></div><ol>${d.ids.map(id=>place(id)).filter(Boolean).map(p=>`<li><span class="overview-place-name">${esc(p.name)}</span></li>`).join('')||'<li>No places yet.</li>'}</ol><span class="hint overview-note">${guided&&state.booking?.date===d.date?'See the booking details below for this date.':'Self-guided · Travel and waiting times not included'}</span></article>`).join('')}${guided&&state.booking?'<p class="hint">Editing your trip does not change a confirmed mate booking.</p>':''}</section>`;}
function sampleDay(){
 return {title:signupText('sampleDay'),date:future(),time:'13:00',party:2,stops:sampleStopIds.map(id=>window.REEL_PLACES.find(p=>p.id===id))};
}
function tripWorkspace(){return `<a href="#board" class="trip-library-shortcut" aria-label="Saved places" title="Saved places">${icon('board')}</a>`;}

function tripPreview(day,cta){
 const rows=day.stops.map((p,i)=>{
  return `<li class="trip-place-row"><span class="trip-place-photo">${placeArt(p)}<b>${i+1}</b></span><div class="trip-place-copy"><strong>${esc(p.name)}</strong><span>${esc(p.area)} · ${esc(p.type)}</span></div></li>`;
 }).join('');
 return `<section class="card pad trip-editor-card trip-plan"><h2>${esc(day.title)}</h2><p>${esc(day.date)}</p>${rows?`<div class="trip-route-heading"><h3>Visit order</h3><span>${day.stops.length} places</span></div><ol>${rows}</ol>`:`<div class="trip-empty"><h3>Start with a place you want to visit</h3><p>Add saved places to start planning your day.</p>${action('Add from saved places','trip-pick-places','secondary')}${btn('Add a new place','manual?from=trips','secondary')}</div>`}${cta}</section>`;
}
function tripDateRange(days){const dates=days.map(d=>d.date).sort();return dates[0]===dates.at(-1)?dates[0]:dates[0]+' ~ '+dates.at(-1);}
function tripListCard(t,requestChoice=false){const ids=[...new Set(t.days.flatMap(d=>d.ids))],first=ids.map(place).find(p=>p?.photoURL||(!window.REEL_MAPS_CONFIG?.apiKey&&p?.photo));return `<button type="button" class="my-trip-card" data-action="${requestChoice===true?'request-trip':'open-trip'}" data-id="${esc(t.id)}"><span class="my-trip-cover">${first?placeArt(first):icon('trips')}</span><span class="my-trip-summary"><strong>${esc(t.title)}</strong><span>${esc(tripDateRange(t.days))}</span><small>${t.days.length} days · ${ids.length} places</small></span><span class="my-trip-chevron" aria-hidden="true">${icon('chevronRight')}</span></button>`;}
function trips(){
 ensureDays();stashDay();stashTrip();if(isTripDetail()){const id=new URLSearchParams(location.hash.split('?')[1]).get('id');if(id&&id!==state.activeTripId&&!selectTrip(id))return `<section class="trip-unavailable" aria-labelledby="trip-unavailable-title"><h2 id="trip-unavailable-title">Trip not found.</h2><p class="muted">This trip may have been deleted, or the link may be incorrect.</p><div class="buttons">${btn('Back to my trips','trips')}</div></section>`;return tripDetail();}
 const today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Seoul'}),past=state.trips.filter(t=>t.days.every(d=>d.date<today)),upcoming=state.trips.filter(t=>!past.includes(t));
 return `<div class="my-trips-heading"><h1>My trips</h1>${tripWorkspace()}</div><button class="trip-create-banner" type="button" data-action="new-trip"><span aria-hidden="true">${icon('plus')}</span><span><strong>Create a trip itinerary</strong><small>Start planning your next trip.</small></span></button>${upcoming.length?`<section class="trip-list-section"><h2>Upcoming trips</h2><div class="my-trip-list">${upcoming.map(tripListCard).join('')}</div></section>`:`<section class="trip-list-section"><h2>Upcoming trips</h2><div class="trip-upcoming-empty"><span aria-hidden="true">${icon('trips')}</span><h3>No upcoming trips yet</h3><p>Create a trip and add the places you want to visit.</p></div></section>`}${past.length?`<section class="trip-list-section"><h2>Past trips</h2><div class="my-trip-list">${past.map(tripListCard).join('')}</div></section>`:''}`;
}
function tripDetailHeader(){ensureDays();return `<header class="trip-detail-header"><a class="app-back" href="#trips" aria-label="My trip list">${icon('chevronLeft')}</a><div><h1>${esc(state.title)}</h1><p>${esc(tripDateRange(state.days))}</p></div><button type="button" class="trip-header-icon" data-action="edit-trip" aria-label="Edit trip details">${icon('edit')}</button></header>`;}
function tripDetail(){
 const next=activeMateStep(),linked=state.request?.tripId===state.activeTripId,stops=state.board.map(place).filter(Boolean);
 const requestAction=next?(linked?btn(next.label,next.route):btn('View your ongoing mate request',next.route,'secondary')):requestStops().length?btn(signupText('tripEstimate'),'request'):'';
 const rows=stops.map((p,i)=>{return `<li class="trip-timeline-stop"><span class="trip-stop-number">${i+1}</span><div class="rt-stop-row"><button class="trip-stop-content ${state.focus===p.id?'is-focused':''}" type="button" data-action="focus-place" data-id="${esc(p.id)}" aria-label="On the map: ${esc(p.name)} view"><span><strong>${esc(p.name)}</strong><small>${esc(p.type)} · ${esc(p.area)}</small></span><span class="trip-stop-photo">${placeArt(p)}</span></button><button type="button" class="iconbtn" data-action="trip-stop-menu" data-id="${esc(p.id)}" aria-label="${esc(p.name)} Place menu" aria-haspopup="dialog">${icon('more')}</button></div>${i<stops.length-1?travelLeg(p,stops[i+1]):''}</li>`;}).join('');
 return `<div class="trip-detail-map">${stops.length?mapPanel():'<div class="trip-map-empty">'+icon('trips')+'<p>Add places to see your route on the map.</p></div>'}</div><section class="trip-detail-sheet"><div class="sheet-handle" aria-hidden="true"></div><div class="trip-day-toolbar">${dayTabs()}</div><div class="trip-day-heading"><h2>Day ${state.day+1}</h2><span><time datetime="${esc(state.date)}">${esc(state.date.slice(5).replace('-','.'))}</time></span></div>${rows?`<ol class="trip-timeline">${rows}</ol>`:`<div class="trip-day-empty"><h3>Where shall we start?</h3><p>Add places you want to visit to your itinerary.</p></div>`}<button class="trip-add-button btn secondary" type="button" data-action="trip-add-menu" aria-haspopup="dialog"><span aria-hidden="true">${icon('plus')}</span>Add to itinerary</button><section class="card rt-mate-invite"><span class="rt-mate-invite-eyebrow">${icon('guides',18)} Travel with a mate</span><h3>Good company,<br>a better journey</h3><p>Discover your favorite places with a mate’s local touch.<br>Find the little moments you might otherwise miss.</p><ul class="rt-mate-invite-moments"><li>${icon('local')}<span>Local discoveries</span></li><li>${icon('cafe')}<span>Cafes you’ll love</span></li><li>${icon('camera')}<span>Photos together</span></li></ul><div class="rt-mate-invite-footer"><p>Get proposals for your trip and choose a mate to join you.</p>${requestAction||'<button class="btn" type="button" data-action="trip-add-menu">'+icon('plus',18)+'Add a place to explore together</button>'}</div></section></section>`;
}
function tripStopMenu(id){const i=state.board.indexOf(id),p=place(id);if(i<0||!p)return;modal(`<div class="trip-menu-heading"><h2>${esc(p.name)}</h2><button type="button" class="textbtn" data-action="close" aria-label="Close">${icon('close')}</button></div><div class="stack">${action(icon('arrowUp',20)+'Move up','trip-stop-move','secondary',`data-id="${esc(id)}" data-dir="-1" ${i===0?'disabled':''}`)}${action(icon('arrowDown',20)+'Move down','trip-stop-move','secondary',`data-id="${esc(id)}" data-dir="1" ${i===state.board.length-1?'disabled':''}`)}${action(icon('trash',20)+'Remove stop','trip-stop-remove','secondary',`data-id="${esc(id)}"`)}</div>`,'trip-menu');}
function moveTripPlace(id,dir){const i=state.board.indexOf(id),j=i+dir;if(i<0||![-1,1].includes(dir)||j<0||j>=state.board.length)return false;[state.board[i],state.board[j]]=[state.board[j],state.board[i]];state.saved=false;save();return true;}
function removeTripPlace(id){if(!state.board.includes(id))return false;state.board=state.board.filter(x=>x!==id);state.must=state.must.filter(x=>x!==id);if(state.focus===id)state.focus=null;state.saved=false;save();return true;}
function updateTripDay(field,value){if(field==='date'){if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||!Number.isFinite(Date.parse(value+'T12:00:00Z'))||dateAfter(value,0)!==value)return false;}else if(field==='time'){if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(value))return false;}else return false;state[field]=value;state.saved=false;save();return true;}
function tripDaySettings(){modal(`<div class="trip-menu-heading"><h2>Day ${state.day+1} · Date</h2><button type="button" class="textbtn" data-action="close" aria-label="Close">${icon('close')}</button></div><label>Date for this day<input type="date" data-trip-day-field="date" required value="${esc(state.date)}"></label><p class="hint">Changes are saved automatically.</p>`,'trip-menu');}
function tripAddMenu(){modal(`<div class="trip-menu-heading"><h2>Add to Day ${state.day+1}</h2><button class="textbtn" type="button" data-action="close" aria-label="Close">${icon('close')}</button></div><button type="button" class="trip-add-option" data-action="trip-pick-places">${icon('board')}<span><strong>Add from saved places</strong><small>Add places you found in videos to your itinerary.</small></span></button><div class="trip-add-grid"><button type="button" data-action="trip-manual">${icon('all')}<strong>Add a new place</strong></button></div>`,'trip-menu');}
function tripPlacePicker(){const places=libraryIds().map(place).filter(Boolean);modal(`<div class="trip-menu-heading"><h2>Saved places</h2>${action('완료','close','secondary small')}</div><p class="hint">Day ${state.day+1} · ${esc(state.date)}</p><div class="trip-place-picker">${places.map(p=>`<div class="trip-picker-row"><span>${placeArt(p)}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.area)} · ${esc(p.type)}</small></div><button class="btn secondary small" type="button" data-action="trip-add-place" data-id="${esc(p.id)}" ${state.board.includes(p.id)?'disabled':''}>${state.board.includes(p.id)?'Added':'추가'}</button></div>`).join('')||'<p>No saved places yet. Try adding a new place.</p>'}</div>`,'trip-menu');}
function addTripPlace(id){if(!libraryIds().includes(id)||!place(id)||state.board.includes(id)||state.board.length>=20)return false;state.board.push(id);state.saved=false;save();return true;}
function editTripInfo(){modal(`<form id="edit-trip-form"><h2>Edit trip details</h2><label>Trip name<input name="title" required maxlength="70" value="${esc(state.title)}"></label><label>Start date<input name="date" type="date" required value="${esc(state.days[0].date)}"></label><p class="hint">Changing the start date shifts every day by the same amount.</p><p id="edit-trip-error" role="alert" class="error"></p><div class="buttons"><button type="submit" class="btn">Save</button>${action('Cancel','close','secondary')}</div></form>`);}
function updateTripInfo(d){const name=String(d.title||'').trim(),date=d.date;if(!name||name.length>70||!/^\d{4}-\d{2}-\d{2}$/.test(date||'')||!Number.isFinite(Date.parse(date+'T12:00:00Z'))||dateAfter(date,0)!==date)return false;stashDay();const shift=Math.round((Date.parse(date)-Date.parse(state.days[0].date))/86400000);state.days.forEach(day=>day.date=dateAfter(day.date,shift));state.date=state.days[state.day].date;state.title=name;state.saved=false;save();return true;}
let guidesTab='requests';
function guideRequests(){
 const r=state.request,list=proposals(),open=r&&['requested','quoted'].includes(r.status)&&!state.booking;
 return `<div class="proposal-inbox">${r?requestInboxCard(r,list,open):`<section class="inbox-empty rt-card-actions-centered rt-card-compact"><span class="inbox-start-icon" aria-hidden="true">${icon('board')}</span><h2>No proposals yet!</h2><p>Choose your destination and travel dates to send a request.<br>Mates can then send you itineraries and prices.</p><button type="button" class="btn" data-action="guides-tab" data-id="discover">Find a travel mate</button></section>`}</div>`;
}
function requestInboxCard(r,list,open){const created=r.createdAt?new Date(r.createdAt).toLocaleDateString(document.documentElement.lang==='en'?'en-US':'ko-KR',{timeZone:'Asia/Seoul',month:'short',day:'numeric'}):'';return `<a href="#requested" class="request-inbox-card"><div class="request-inbox-meta"><span class="request-inbox-status ${open?(list.length?'rt-status-text-primary':'is-open'):state.booking?'':'rt-status-text-ink'}">${open?(list.length?'Proposals received':'Awaiting proposals'):state.booking?'Mate selected':'Close request'}</span><span>${esc(created)}</span></div><div class="request-inbox-title"><h4>${esc(r.tripTitle||state.title)}</h4><span>Proposals ${list.length} <b aria-hidden="true">${icon('chevronRight')}</b></span></div><p class="request-inbox-facts">${requestPeriod(r)} · ${r.party} ${r.party===1?"guest":"guests"} · ${r.requestType==='free'?'자유 견적':(r.stops||[]).length+' places'}</p></a>`;}


const nicknameDirectoryKey='reeltrip-prototype-nicknames-v1',nicknameOwner='traveler-demo';
let checkedNickname='';
const normalizeNickname=value=>String(value||'').normalize('NFKC').replace(/\s+/gu,'').toLowerCase();
function readNicknameDirectory(){const raw=JSON.parse(localStorage.getItem(nicknameDirectoryKey)||'{}');if(!raw||typeof raw!=='object'||Array.isArray(raw))throw new Error('Invalid nickname directory');const directory=Object.fromEntries(Object.entries(raw).filter(([,owner])=>owner!=='mate-demo'));const mate=JSON.parse(localStorage.getItem('reeltrip-mate-application-v1')||'null');if(mate?.fields?.name){const name=normalizeNickname(mate.fields.name);if(!directory[name])directory[name]='mate-demo';}return {...directory,[normalizeNickname('\uBBF8\uB098')]:'mate-mina',[normalizeNickname('\uC900')]:'mate-jun'};}
function nicknameProblem(value,directory,currentOwner=nicknameOwner){const display=String(value||'').normalize('NFKC').trim(),canonical=normalizeNickname(display);if(display.length<2||display.length>20||canonical.length<2)return 'Enter a nickname with 2–20 characters.';if(/[\p{Cc}\p{Cf}]/u.test(display))return 'This nickname contains unsupported characters.';if(['\uB9B4\uD2B8\uB9BD','reeltrip','\uC6B4\uC601\uD300','\uACE0\uAC1D\uC13C\uD130','\uAD00\uB9AC\uC790'].some(word=>canonical.includes(word)))return 'Names that could impersonate staff are not allowed.';const owner=directory[canonical];return owner&&owner!==currentOwner?'This nickname is taken. Try another name.':'';}
function setNicknameStatus(text='',valid=null){const input=$('#profile-nickname'),message=$('#nickname-status');message.textContent=text;if(valid===null)delete message.dataset.valid;else message.dataset.valid=String(valid);input.setAttribute('aria-invalid',String(valid===false));}
function checkNickname(){const input=document.querySelector('#profile-form [name="nickname"]');checkedNickname='';try{const problem=nicknameProblem(input.value,readNicknameDirectory());setNicknameStatus(problem||'This nickname is available.',!problem);if(!problem)checkedNickname=normalizeNickname(input.value);}catch{setNicknameStatus('Could not check availability. Please try again.',false);}}
function mateNameProblem(value){try{return nicknameProblem(value,readNicknameDirectory(),'mate-demo');}catch{return 'Could not check availability. Please try again.';}}
function checkMateName(){const input=$('#mate-name'),message=$('#mate-name-status'),editing=!!$('#mate-edit-form'),a=editing?mateEditDraft:mateApplication();if(editing?!canEditMate():['pending','approved'].includes(a.status))return;const problem=mateNameProblem(input.value);message.textContent=problem||'This nickname is available.';input.setAttribute('aria-invalid',String(!!problem));a.fields.name=input.value.normalize('NFKC').trim();a.fields.nameChecked=problem?'':normalizeNickname(input.value);if(!editing)saveMate(a);}
