let matePhotoRead=0;
function readMatePhoto(input){const file=input.files?.[0];if(!file)return;const token=++matePhotoRead,error=$('#mate-photo-error');if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>1048576){error.textContent='Choose a JPG, PNG or WebP photo up to 1MB.';input.value='';return;}error.textContent='';const reader=new FileReader();reader.onload=()=>{const a=mateApplication();if(token!==matePhotoRead||['pending','approved'].includes(a.status))return;a.fields.photo=reader.result;if(saveMate(a)&&$('#mate-photo-preview')){$('#mate-photo-preview').innerHTML=profileAvatar(a.fields.photo);if($('#mate-photo-clear'))$('#mate-photo-clear').hidden=false;if($('#mate-camera-button'))$('#mate-camera-button').hidden=true;}};reader.onerror=()=>{if($('#mate-photo-error'))$('#mate-photo-error').textContent='Could not load this photo. Please try again.';};reader.readAsDataURL(file);}
function matePhotoEditor(a){return `<div class="mate-photo-editor"><span class="mate-field-label" id="mate-photo-label">Profile photo</span>${profilePhotoControl('mate',a.fields.photo||'','mate-photo-remove')}<small>We recommend a photo that clearly shows your face.</small><p id="mate-photo-error" role="alert"></p></div>`;}
function mateSummary(a){const f=a.fields;return `<div class="rt-review-stack">${matePublicPreview(a)}<section class="rt-review-section"><h2>The information below is not public</h2><dl class="rt-fact-list">${[['Contact',f.contact]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'—')}</dd></div>`).join('')}</dl></section></div>`;}
function mateField(a,name,label,extra='',area=false,required=true){return `<label>${label}${area?`<textarea name="${name}" ${required?'required':''} ${extra}>${esc(a.fields[name]||'')}</textarea>`:`<input name="${name}" ${required?'required':''} value="${esc(a.fields[name]||'')}" ${extra}>`}</label>`;}
// UI-only verification. Never use this browser-local state as proof of phone ownership.
let matePhoneDemo={phone:'',sentAt:0,verified:false,attempts:0};
const matePhoneDigits=value=>String(value||'').replace(/[^0-9]/g,'');
function matePhoneVerified(a){return matePhoneDemo.verified&&matePhoneDemo.phone===matePhoneDigits(a.fields.contact);}
function matePhoneUI(a){const verified=matePhoneVerified(a),sent=matePhoneDemo.sentAt&&matePhoneDemo.phone===matePhoneDigits(a.fields.contact);return `<p class="hint">SMS verification demo. No real text messages are sent.</p>${verified?'':`<button type="button" class="btn secondary" data-action="mate-phone-send">${sent?'Resend code':'Get verification code'}</button>`}${sent&&!verified?`<p class="hint">Demo code: 123456 · Valid for 3 minutes · Resend after 30 seconds.</p><label>6-digit verification code<input id="mate-phone-code" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="6" pattern="[0-9]{6}" placeholder="6 digits" aria-describedby="mate-phone-status"></label><button type="button" class="btn secondary" data-action="mate-phone-verify">Verify code</button>`:''}<p id="mate-phone-status" role="status" aria-live="polite">${verified?'Verification complete.':''}</p>`;}
function matePhoneAction(kind){const form=$('#mate-form');if(!form||isGuest())return;const a=captureMate(form,mateApplication());if(['pending','approved'].includes(a.status))return;if(!validMatePhone(a.fields.contact)){toast('Enter a valid Korean mobile phone number starting with 010.');return;}const phone=matePhoneDigits(a.fields.contact),now=Date.now();if(kind==='send'){if(matePhoneDemo.sentAt&&now-matePhoneDemo.sentAt<30000){toast('Please wait 30 seconds before resending.');return;}matePhoneDemo={phone,sentAt:now,verified:false,attempts:0};saveMate(a);render();$('#mate-phone-code')?.focus();return;}const message=$('#mate-phone-status'),code=$('#mate-phone-code')?.value||'';if(!message)return;if(phone!==matePhoneDemo.phone||!matePhoneDemo.sentAt){message.textContent='Request a verification code first.';return;}if(now-matePhoneDemo.sentAt>=180000){message.textContent='The code has expired. Please request another.';return;}if(matePhoneDemo.attempts>=5){message.textContent='Too many attempts. Please request another code.';return;}if(!/^[0-9]{6}$/.test(code)){message.textContent='Enter the 6-digit verification code.';return;}matePhoneDemo.attempts++;if(code!=='123456'){message.textContent='The verification code does not match.';return;}matePhoneDemo.verified=true;saveMate(a);render();}
function mateRegistration(){
 const a=mateApplication(),step=Math.min(4,Math.max(1,a.step||1));
 if(['pending','approved'].includes(a.status))return `<section class="mate-onboarding rt-card-stack"><section class="card pad rt-status-card rt-card-actions-centered"><span class="rt-status-symbol" aria-hidden="true">${icon(a.status==='approved'?'check':'clock',32)}</span>${a.status==='pending'?`<span class="badge">${mateStatus(a.status)}</span>`:''}<h1>${a.status==='approved'?'You are now registered as a mate':'Your application is under review'}</h1><p>${a.status==='approved'?'You can now switch to mate mode to view trips and send proposals.':'You can start as a mate once an administrator approves your application!'}</p>${a.status==='approved'?'<button class="btn" data-access-mode="guide">Switch to mate mode</button>':''}</section><details class="card rt-disclosure-card"><summary><span>View submitted application</span>${icon('chevronDown',20)}</summary><div class="rt-disclosure-body">${mateSummary(a)}</div></details>${a.status==='pending'?'<p class="rt-status-note">You can still use traveler features while your application is under review.</p>':''}</section>`;
 let body='';
 if(step===1)body=`<h1>Where can you join travelers?</h1><p>Choose your activity areas and one language.</p><div class="mate-field"><span>Activity area</span><button class="mate-region-trigger" type="button" data-action="mate-region-open">${esc(mateRegionText(a.fields.regions)||'Select activity areas')}<span aria-hidden="true">${icon('plus')}</span></button></div><fieldset class="mate-language"><legend>Language</legend><p>Select all languages you can use to communicate with travelers.</p><div class="rt-multi-choice-group">${Object.entries(mateLanguages).map(([id,label])=>`<label class="rt-multi-choice"><input type="checkbox" name="languages" value="${id}" ${mateLanguageValues(a.fields.languages).includes(id)?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset>`;
 if(step===2)body=`${matePhotoEditor(a)}${mateNameField(a)}${mateField(a,'bio','Introduction','class="rt-textarea-large" rows="8" minlength="10" maxlength="1000" placeholder="Tell travelers about your connection to the area, your walking style and how you can help."',true)}`;
 if(step===3)body=`<h1>What is your mobile phone number?</h1>${mateField(a,'contact','Mobile phone number','type="tel" inputmode="tel" autocomplete="tel-national" maxlength="13" pattern="010[ -]?[0-9]{4}[ -]?[0-9]{4}" placeholder="010-1234-5678"')}${matePhoneUI(a)}<button type="button" class="textbtn" data-action="mate-contact-support">Don’t have a mobile phone number?</button>`;
 if(step===4)body=`<h1>Review before submitting</h1>${mateSummary(a)}<label class="check"><input type="checkbox" name="policy" required ${a.fields.policy?'checked':''}>I understand that after traveler selection, I must pay the 10% matching fee to confirm the booking, and collect the trip price directly in cash on site.</label><label class="check"><input type="checkbox" name="consent" required ${a.fields.consent?'checked':''}>I agree to the use of this information for review and publication of my public profile after approval.</label><p class="muted">You can start as a mate once an administrator approves your application!</p>`;
 return `<section class="mate-onboarding"><header><a href="#account">Close · resume later</a><strong>Mate registration</strong></header>${step===2?'':`<div class="mate-progress"><progress max="4" value="${step}" aria-label="Registration progress"></progress><span>${step} / 4</span></div><p class="eyebrow">${mateSteps[step-1]}</p>`}${['needs_info','rejected'].includes(a.status)?`<aside class="notice"><strong>${mateStatus(a.status)}</strong><p>${esc(a.reason)}</p><p>Update your information and submit it for review again.</p></aside>`:''}<form id="mate-form" data-step="${step}">${body}<div class="mate-form-actions">${step>1?'<button type="button" class="btn secondary" data-action="mate-back">이전</button>':''}<button class="btn" type="submit">${step===4?'Submit for review':'다음'}</button></div></form></section>`;
}
function captureMate(f,a){const languageInputs=Array.from(f.elements).filter(el=>el.name==='languages'&&el.type==='checkbox');if(languageInputs.length)a.fields.languages=languageInputs.filter(el=>el.checked).map(el=>el.value);for(const el of f.elements){if(el.name==='languages'&&el.type==='checkbox')continue;if(!el.name||el.type==='file')continue;if(el.type==='radio'){if(el.checked)a.fields[el.name]=el.value;}else a.fields[el.name]=el.type==='checkbox'?el.checked:el.value;}if(a.fields.nameChecked!==normalizeNickname(a.fields.name))delete a.fields.nameChecked;return a;}
function validMatePhone(value){return /^010[ -]?[0-9]{4}[ -]?[0-9]{4}$/.test(String(value||'').trim());}
function validMate(a){const f=a.fields;return ['languages','name','bio','contact'].every(k=>String(f[k]||'').trim())&&validMateRegions(f.regions)&&validMateLanguages(f.languages)&&f.name.trim().length>=2&&!mateNameProblem(f.name)&&f.bio.trim().length>=10&&f.bio.length<=1000&&!!f.photo&&validMatePhone(f.contact)&&f.policy&&f.consent;}
function submitMate(f){const a=mateApplication();if(['pending','approved'].includes(a.status))return;captureMate(f,a);if([3,4].includes(a.step)&&!matePhoneVerified(a)){a.step=3;saveMate(a);render();toast('Please complete phone verification.');return;}if(a.step===3&&!validMatePhone(a.fields.contact)){toast('Enter a valid Korean mobile phone number starting with 010.');return;}if(a.step===1&&(!validMateRegions(a.fields.regions)||!validMateLanguages(a.fields.languages))){toast('Select your activity areas and language.');return;}if(a.step===2&&(!a.fields.photo||!a.fields.name?.trim()||a.fields.name.trim().length<2||!a.fields.bio||a.fields.bio.trim().length<10||a.fields.bio.length>1000)){toast('Add a profile photo, activity name and introduction. All are required.');return;}if(a.step===2||a.step===4){const problem=mateNameProblem(a.fields.name);if(problem){toast(problem);return;}if(a.fields.nameChecked!==normalizeNickname(a.fields.name)){toast('Check nickname availability first.');return;}}if(a.step===4){if(!validMate(a)){toast('Check the required information.');return;}a.status='pending';a.submittedAt=new Date().toISOString();a.reason='';}else a.step=(a.step||0)+1;if(saveMate(a)){render();resetMateScroll();}}
function mateAdmin(){const a=mateApplication();return side('admin',`${title('Mate application review','Review application','')}<section class="card pad"><span class="badge">${mateStatus(a.status)}</span>${a.status==='draft'?'<p>No submitted applications.</p>':`${mateSummary(a)}${a.reason?`<p class="notice">${esc(a.reason)}</p>`:''}${a.status==='pending'?`<form id="mate-review-form">${['I reviewed the area, languages and introduction','I reviewed contact, identity and qualification checks','I checked agreement to the matching fee and cash payment terms'].map(t=>`<label class="check"><input type="checkbox" name="reviewCheck" required>${t}</label>`).join('')}<label>Reason for changes or rejection<textarea name="reason" maxlength="1000" placeholder="Describe the changes the applicant needs to make"></textarea></label><div class="buttons"><button class="btn" type="submit">Approve registration</button><button class="btn secondary" type="button" data-action="mate-review" data-id="needs_info">More information needed</button><button class="btn secondary" type="button" data-action="mate-review" data-id="rejected">Declined</button></div></form>`:''}`}</section>`);}
function reviewMate(status,reason=''){if(!window.ReelAccess.isAdmin)return false;const a=mateApplication();if(a.status!=='pending')return false;if(status!=='approved'&&!reason.trim()){toast('Enter a reason for requesting changes or rejecting the application.');return false;}a.status=status;a.reason=reason.trim();a.reviewedAt=new Date().toISOString();return saveMate(a);}

// Approved mate edits stay in memory until explicit save.
let mateEditDraft=null,mateEditSection='profile',mateEditPhotoLoading=false;
function canEditMate(){return !isGuest()&&window.ReelAccess.mode()==='guide'&&mateApplication().status==='approved';}
function editMate(section,resume=false){
 if(!canEditMate())return;
 if(!resume){mateEditDraft=mateApplication();mateEditSection=section;mateEditPhotoLoading=false;matePhotoRead++;}
 const a=mateEditDraft,f=a.fields;
 const body=mateEditSection==='profile'?`${profilePhotoControl('mate-edit',f.photo||'','mate-edit-photo-remove')}<p class="hint">JPG·PNG·WebP · Up to 1MB</p>${mateNameField(a)}${mateField(a,'bio','Introduction','class="rt-textarea-large" rows="8" minlength="10" maxlength="1000"',true)}`:`<label>Specialty<select name="specialty" required><option value="">Choose a specialty</option>${mateSpecialties.map((label,i)=>`<option value="${i}" ${String(f.specialty)===String(i)?'selected':''}>${label}</option>`).join('')}</select></label><div class="mate-field"><span>Activity area</span><button type="button" class="mate-region-trigger" data-action="mate-edit-region">${esc(mateRegionText(f.regions)||'Select activity areas')}${icon('plus')}</button></div><fieldset class="mate-language"><legend>Language</legend><div class="rt-multi-choice-group">${Object.entries(mateLanguages).map(([id,label])=>`<label class="rt-multi-choice"><input type="checkbox" name="languages" value="${id}" ${mateLanguageValues(f.languages).includes(id)?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset>`;
 modal(`<form id="mate-edit-form"><h2>${mateEditSection==='profile'?'Edit mate profile':'Edit mate activity information'}</h2>${body}<p id="mate-edit-error" class="error" role="alert"></p><div class="buttons">${action('Cancel','close','secondary')}<button type="submit" class="btn" id="mate-edit-save">Save</button></div></form>`);
}
function saveMateEdit(form){
 if(!canEditMate()||!mateEditDraft||mateEditPhotoLoading)return;
 captureMate(form,mateEditDraft);const f=mateEditDraft.fields,current=mateApplication();let problem='';
 if(mateEditSection==='profile'){
  f.name=String(f.name||'').normalize('NFKC').trim();f.bio=String(f.bio||'').trim();
  const changed=f.name!==current.fields.name;
  problem=changed?mateNameProblem(f.name):'';
  if(!problem&&(f.bio.length<10||f.bio.length>1000))problem='Enter a bio of 10–1,000 characters.';
  if(!problem&&changed&&f.nameChecked!==normalizeNickname(f.name))problem='Check nickname availability first.';
 }else if(!validMateRegions(f.regions)||!validMateLanguages(f.languages)||!/^\d+$/.test(String(f.specialty))||!mateSpecialties[Number(f.specialty)])problem='Choose a specialty, regions and languages.';
 if(problem){$('#mate-edit-error').textContent=problem;return;}
 const keys=mateEditSection==='profile'?['name','nameChecked','photo','bio']:['specialty','regions','languages'];
 for(const key of keys)current.fields[key]=f[key];
 if(mateEditSection==='activity'){current.fields.region=mateRegionText(f.regions);delete current.fields.range;}
 if(saveMate(current)){mateEditDraft=null;$('#dialog').close();render();toast('Your mate information has been saved.');}
}
function readMateEditPhoto(input){
 const file=input.files?.[0],draft=mateEditDraft;if(!file||!draft)return;
 const error=$('#mate-edit-error');if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>1048576){error.textContent='Choose a JPG, PNG or WebP photo up to 1MB.';input.value='';return;}
 const token=++matePhotoRead,form=$('#mate-edit-form');mateEditPhotoLoading=true;$('#mate-edit-save').disabled=true;error.textContent='';
 const reader=new FileReader();const active=()=>token===matePhotoRead&&draft===mateEditDraft&&form===$('#mate-edit-form')&&$('#dialog').open;
 reader.onload=()=>{if(!active())return;draft.fields.photo=reader.result;mateEditPhotoLoading=false;$('#mate-edit-save').disabled=false;$('#mate-edit-photo-preview').innerHTML=profileAvatar(reader.result);$('#mate-edit-photo-clear').hidden=false;$('#mate-edit-camera-button').hidden=true;};
 reader.onerror=()=>{if(!active())return;mateEditPhotoLoading=false;$('#mate-edit-save').disabled=false;error.textContent='Could not load this photo. Please try again.';};reader.readAsDataURL(file);
}

function mateAccount(){
 const a=mateApplication(),f=a.fields||{};
 const rows=[['Specialty',f.specialty!==undefined?mateSpecialties[Number(f.specialty)]:''],['Activity area',mateRegionText(f.regions)],['Language',mateLanguageText(f.languages)]];
 return `<section class="my-page"><div class="my-heading"><h1>My account</h1><a class="my-settings-button" href="#settings" aria-label="Settings">${icon('settings')}</a></div><div class="rt-card-stack"><section class="card pad rt-profile-card"><div class="rt-profile-identity"><span class="my-avatar">${profileAvatar(f.photo||'')}</span><div><span class="rt-profile-label">Mate profile</span><h2>${esc(f.name||'Mates')}</h2></div></div><p class="rt-profile-bio">${esc(f.bio||'No introduction has been added.')}</p><div class="rt-card-actions"><button type="button" class="btn secondary small" data-action="mate-edit-profile">${icon('edit',18)} Edit profile</button><button type="button" class="btn secondary small" data-action="mate-preview-profile">View public profile</button></div></section><section class="card pad rt-info-card"><h2>Mate activity information</h2>${rows.some(([,value])=>value)?`<dl class="rt-fact-list">${rows.filter(([,value])=>value).map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`:'<p class="rt-info-note">No activity information has been added.</p>'}<div class="rt-card-actions"><button type="button" class="btn secondary small" data-action="mate-edit-activity">${icon('edit',18)} Edit activity information</button></div></section><section class="card pad rt-info-card rt-info-card--private"><h2>${icon('lock',18)}Application information<span class="rt-private-label">Private</span></h2><dl class="rt-fact-list"><div><dt>Contact</dt><dd>${esc(f.contact||'—')}</dd></div></dl><p class="rt-info-note">Your contact and review information are not shown publicly.</p></section></div></section>`;
}
function account(){
 if(window.ReelAccess.mode()==='guide')return mateAccount();
 return `<section class="my-page"><div class="my-heading"><h1>My account</h1><a class="my-settings-button" href="#settings" aria-label="Settings">${icon('settings')}</a></div><button type="button" class="my-profile" data-action="edit-profile" aria-label="Edit profile"><span class="my-avatar">${profileAvatar()}</span><span class="my-profile-copy"><strong>${esc(state.profile?.nickname||'Traveler')}</strong><small>${state.profile?.nickname?'Edit profile':'Add your nickname and photo'}</small></span><span class="profile-edit-chevron" aria-hidden="true">${icon('chevronRight')}</span></button>${window.ReelAccess.mode()==='guide'?'':mateEntry()}</section>`;}


// Account deletion is browser-local until server authentication is integrated.
function withdrawalKeys(){return ['ko','en'].flatMap(lang=>['', '-comparison'].map(suffix=>`reeltrip-demo-${lang}-map-v2-option-2${suffix}`));}
function withdrawalBlocked(){
 const records=[state,...withdrawalKeys().map(k=>JSON.parse(localStorage.getItem(k)||'null')).filter(Boolean)];
 return records.some(record=>[record.booking,...(record.bookingHistory||[])].some(b=>b&&!['completed','cancelled','cancellation_requested'].includes(b.status)));
}
function withdrawalDialog(){
 if(isGuest()||window.ReelAccess.isAdmin)return;
 try{if(withdrawalBlocked()){modal(`<h2>You have an active booking</h2><p>You can delete your account after your trip or cancellation is complete. Check bookings made in the other language too.</p><div class="buttons">${action('Close','close','secondary')}${action('Help and support','withdrawal-support')}</div>`);return;}}
 catch{toast('Could not check your saved data. Please try again.');return;}
 modal(`<form id="withdraw-account-form"><h2>Delete account</h2><p>Deleting your account ends both traveler and mate activity.</p><ul><li>Your profile, saved places, trips, requests, proposals, chats and support history will be deleted.</li><li>Your mate application and permissions will also be deleted.</li><li>Saved data in both Korean and English apps will be deleted and cannot be recovered.</li></ul><p class="hint">This prototype only deletes saved data and membership status in this browser. Live account deletion is not connected.</p><label><input type="checkbox" name="agree" required> I understand what will be deleted and agree to delete my account.</label><p id="withdraw-account-error" class="error" role="alert"></p><div class="buttons">${action('Cancel','close','secondary')}<button type="submit" class="btn danger">Delete account</button></div></form>`);
}
function withdrawAccount(form){
 if(isGuest()||window.ReelAccess.isAdmin||!form.elements.agree.checked)return;
 const error=$('#withdraw-account-error');
 try{
  if(withdrawalBlocked()){error.textContent='Please resolve your active bookings first.';return;}
  const directory=readNicknameDirectory();
  const retained=Object.fromEntries(Object.entries(directory).filter(([,owner])=>![nicknameOwner,'mate-demo'].includes(owner)));
  localStorage.setItem(nicknameDirectoryKey,JSON.stringify(retained));
  for(const k of [...withdrawalKeys(),sharedNicknameKey,mateKey,'reeltrip-prototype-access-v1'])localStorage.removeItem(k);
  sessionStorage.removeItem(memberSessionKey);
 }catch{error.textContent='Account deletion could not be completed. Please try again.';return;}
 clearTimeout(timer);previewMember=false;state=initial();window.ReelAccess.reset();
 pendingRestaurant=null;pendingEstimate=false;pendingRequestRoute=null;pendingRecommendation=null;profileDraftPhoto='';checkedNickname='';
 $('#dialog').close();go('home');render();toast('Your account data in this browser has been deleted.');
}

function settingsPage(){return `<section class="settings-page">${window.ReelAccess.settings().replace(/<div class="account-setting-row">[\s\S]*?<\/a><\/div>/,()=>signupLanguageLink(true))}<section class="settings-group"><h2>Customer support</h2><a href="#settings" data-action="blocked-users">Blocked users<span>${icon('chevronRight')}</span></a><a href="#support">Help and support<span>${icon('chevronRight')}</span></a><a href="#policies?section=terms">Terms of Service<span>${icon('chevronRight')}</span></a></section><section class="settings-group"><h2>Account</h2><a href="#settings" data-action="withdraw-account">Delete account<span>${icon('chevronRight')}</span></a></section></section>`;}

function support(){const query=new URLSearchParams(location.hash.split('?')[1]||'').get('placeQuery')||'';return `<div class="centerbox">${title('Help','How can we help?','')}<div class="card pad"><h2 class="support-group-title">Common questions</h2><details><summary>Can I find a place without knowing its Korean name?</summary><p class="muted small">A public video link can suggest places. Some videos cannot be analyzed. If several branches share a name, compare their addresses.</p></details><details style="margin-top:16px"><summary>${guided?'Can my mate book a restaurant for me?':'Does saving a place reserve a table?'}</summary><p class="muted small">${guided?'Saving a place or requesting a mate does not reserve a table. Describe the help you need and check what is included in the final proposal.':'Saving places helps you plan visits. Restaurant bookings and ordering assistance are not included. Check reservation requirements with the venue.'}</p></details><details style="margin-top:16px"><summary>Why was a place not found?</summary><p class="muted small">Private videos, unclear names or multiple branches can make places hard to identify. Try a public link or add a place yourself.</p></details></div><form id="support-form" class="card pad" style="margin-top:20px"><h2 class="support-group-title">Write a message</h2><label>Topic<select name="type"><option>Place or video issue</option><option>Data or privacy request</option>${guided?'<option>Booking or refund</option>':''}<option>Other feedback</option></select></label><label style="margin-top:17px">How can we help?<textarea name="body" minlength="10" maxlength="1000" required placeholder="Which place or step do you need help with? Write in the language you are comfortable with. At least 10 characters.">${query?esc(`Place search inquiry: ${query}\nPlease add the area or address of the place you are looking for.`):''}</textarea></label><button type="submit" class="btn" style="margin-top:18px">Save message</button></form></div>`;}
function policySection(){return new URLSearchParams(location.hash.split('?')[1]||'').get('section');}
function policies(){const section=policySection();const heading=section==='privacy'?'Privacy Policy':section==='terms'?'Terms of Service':'Service information';return `<article class="legalcopy">${section==='privacy'||section==='terms'?title(heading,heading):''}${section==='privacy'?`<h2>Saving your trip</h2><p>Your trip is saved in this browser only. It does not sync automatically and may be lost if browser data is cleared.</p><h2>Privacy</h2><p>실제 결제정보Me 민감한 Privacy는 입력하지 마세요.</p>`:section==='terms'?`<h2>Places and maps</h2><p>Photos and maps help you explore. Check current hours, the correct branch and entrance before visiting. Map lines show visit order, not actual directions.</p><h2>Photos and content</h2><p>Open the original video using its link. Photos may not reflect how a place looks today.</p>`:`<h2>Places and maps</h2><p>Photos and maps help you explore. Check current hours, the correct branch and entrance before visiting. Map lines show visit order, not actual directions.</p><h2>Saving your trip</h2><p>Your trip is saved in this browser only. It does not sync automatically and may be lost if browser data is cleared.</p><h2>Privacy</h2><p>실제 결제정보Me 민감한 Privacy는 입력하지 마세요.</p><h2>Photos and content</h2><p>Open the original video using its link. Photos may not reflect how a place looks today.</p>`}${section!=='privacy'?'<h2>Released selections and new proposals</h2><p>If a mate declines before confirmation or misses the fee deadline, your trip automatically receives proposals again as long as it has not started. You can select another valid proposal immediately. If the trip start time has passed, change your dates and submit a new request. Withdrawing your request or cancelling a confirmed booking does not automatically reopen proposals.</p>':''}</article>`;}
function guides(){return `${title('','Mates')}<div class="trip-mode-tabs" role="group" aria-label="Mate menu"><button type="button" data-action="guides-tab" data-id="requests" aria-pressed="${guidesTab==='requests'}">${icon('board')}<span>Received proposals</span>${proposals().length?`<span class="trip-request-count">${proposals().length}</span>`:''}</button><button type="button" data-action="guides-tab" data-id="discover" aria-pressed="${guidesTab==='discover'}">${icon('guides')}<span>Get proposals</span></button></div><section class="trip-tab-panel">${guidesTab==='requests'?guideRequests():guideDiscovery()}</section>`;}

function guideDiscovery(){const next=activeMateStep(),hasTrips=Boolean(state.trips?.length);return `<div class="proposal-request-options"><section class="free-quote-intro"><header class="free-quote-heading"><h2>Find a mate for my trip</h2><p>Get proposals for your trip and choose a mate to join you.</p></header><div class="free-quote-action">${hasTrips?btn('Choose from My trips','request'):action('Create a trip itinerary','new-trip')}</div></section><section class="free-quote-intro"><header class="free-quote-heading"><h2>Plan a trip with a mate</h2><p>Request a quote without a fixed itinerary.<br>Choose your area and dates to receive an itinerary and full quote from a mate.</p></header><div class="free-quote-action">${next?`<p class="free-quote-status">Review your current request or booking first.</p>${btn(next.label,next.route,'secondary')}`:btn('Find a travel mate','request?mode=free','secondary')}</div></section></div>`;}



function journeySummary(q,priceLabel='Total for your group'){return `<section class="journey-summary"><div class="journey-guide"><span class="portrait">${esc(q.guide[0])}</span><div><h2>${esc(q.guide)}${q.guide==='Not matched yet'?'':' Mates'}</h2><p>English Information · ${esc(q.region||'Destination')}</p></div></div><div class="journey-facts"><div><span>Travel date</span><strong>${requestPeriod(q)}</strong></div><div><span>Start time · KST</span><strong>${esc(q.time)}</strong></div><div><span>Your group</span><strong>${q.party} ${q.party===1?"guest":"guests"}</strong></div><div><span>Request type</span><strong>${q.requestType==='free'?'자유 견적':'My itinerary'}</strong></div></div>${q.amount!==undefined?`<div class="journey-price"><span>${priceLabel} · KRW</span><strong>${money(q.amount)}</strong><p>Food, transport, shopping and entry fees are extra.</p></div>`:`<div class="journey-price pending"><span>Mate fee</span><strong>Price on request</strong><p>No payment now. Review your proposal before booking.</p></div>`}</section>`;}
function mateRequestSummary(q){return `<section class="mate-request-summary" aria-label="Trip request summary"><h2>${q.requestType==='free'?esc(q.region||'Destination')+' · 자유 견적':'Trip requests'}</h2><p>${requestPeriod(q)} · ${esc(q.time)} · ${q.party} ${q.party===1?"guest":"guests"}</p><span>Start time is in Korea Standard Time.</span>${q.amount!==undefined?`<div class="summaryrow"><span>Cash to receive in person</span><b>${money(q.amount)}</b></div>`:''}</section>`;}
function journeyPlan(plan){return `<ol class="journey-plan">${String(plan||'').split('\n').filter(line=>line.trim()).map((line,i)=>`<li><b>${i+1}</b><span>${esc(line.replace(/^\d+[.)]\s*/,''))}</span></li>`).join('')}</ol>`;}
function guidePage(){
 const params=new URLSearchParams(location.hash.split('?')[1]||'');
 if(params.get('mate')==='self'){const a=mateApplication();return `${title('','Meet your mate','')}${a.status==='approved'?matePublicProfile(a.fields,true):empty('Public profile not found.','You can view your public profile after approval.','account','My account')}`;}
 const proposalId=params.get('proposal'),q=proposalId?proposals().find(item=>item.id===proposalId):null;
 if(proposalId&&!q)return empty('Public profile not found.','Select a mate again from your received proposals.','requested','Received proposals');
 const mate=(q?q.guideId:state.guide)==='jun'?'jun':'mina';
 const f={name:q?q.guide:mate==='jun'?'Jun':'Mina',photo:'',region:signupText(mate+'Area'),languages:['en','ko'],bio:signupText(mate+'Intro')};
 return `${title('','Meet your mate','')}${matePublicProfile(f,true)}${q?btn(`${icon('chevronLeft',20)}<span>Back to received proposals</span>`,'requested','secondary rt-return-button'):''}`;
}

function requestPeriod(r){return r.endDate&&r.endDate!==r.date?`${esc(r.date)} ~ ${esc(r.endDate)}`:esc(r.date);}
function tripLength(n){return n===1?'Day trip':`${n-1} nights / ${n} days`;}
function dateAfter(date,offset){return new Date(Date.parse(date+'T12:00:00Z')+offset*86400000).toISOString().slice(0,10);}
function itineraryRequestDays(example=false){
 if(example){const d=sampleDay();return [{date:d.date,time:d.time,stops:d.stops.map(p=>({...p}))}];}
 stashDay();return state.days.map(d=>({date:d.date,time:d.time,stops:d.ids.map(place).filter(Boolean).map(p=>({...p,duration:d.durations?.[p.id]||p.duration}))}));
}
function requestPlan(r){return (r.days?.length?r.days:[{date:r.date,stops:r.stops||[]}]).map((d,i)=>`Day ${i+1} · ${d.date}\n${d.stops.length?d.stops.map(p=>p.name).join('\n'):'Your mate will propose places to visit.'}`).join('\n');}
function submitTravelRequest(d,{free=false,example=false}={}){
 if(activeMateStep())return {route:activeMateStep().route};
 if(!free&&!example&&d.tripId&&!selectTrip(d.tripId))return {error:'Please select your trip again.'};
 let days=free?[]:itineraryRequestDays(example);
 const count=Number(d.dayCount),party=Number(d.party),region=String(d.region||'').trim();
 if(free&&(!region||region.length>80))return {error:'Select your destination.'};
 if(free&&(!Number.isInteger(count)||count<1||count>7))return {error:'Choose a trip length from 1 to 7 days.'};
 if(!Number.isInteger(party)||party<1||party>99)return {error:'Enter 1 to 99 travelers.'};
 const start=free?d.date:days[0]?.date,time=free?d.time:days[0]?.time;
 if(!/^\d{4}-\d{2}-\d{2}$/.test(start||'')||!/^([01]\d|2[0-3]):[0-5]\d$/.test(time||'')||!Number.isFinite(Date.parse(`${start}T${time}:00+09:00`))||Date.parse(`${start}T${time}:00+09:00`)<Date.now()+48*3600000)return {error:'Choose a start date and time at least 48 hours from now.'};
 if(dateAfter(start,0)!==start)return {error:'Choose a valid date.'};
 if(free)days=Array.from({length:count},(_,i)=>({date:dateAfter(start,i),time,stops:[]}));
 if(!days.length||days.length>7||days.some((day,i)=>!Number.isFinite(Date.parse(day.date+'T12:00:00Z'))||(i&&day.date<=days[i-1].date))||Date.parse(days.at(-1).date)-Date.parse(start)>6*86400000)return {error:'Arrange your itinerary dates in order within a 7-day period.'};
 const stops=days.flatMap(day=>day.stops);
 if(!free&&!stops.length)return {error:'Add saved places to your trip first.'};
 if(!free&&days.some(day=>day.stops.length>20))return {error:'You can request up to 20 places per day.'};
 if(!d.guideAck||!d.ack)return {error:'Confirm the sharing and booking request notices.'};
 syncConversations();
 state.request={id:'RQ-DEMO-'+Date.now(),status:'requested',visibility:'approved_mates',requestType:free?'free':'itinerary',region:free?region:[...new Set(stops.map(p=>p.area))].join(', '),date:start,endDate:days.at(-1).date,dayCount:days.length,time,party,days:JSON.parse(JSON.stringify(days)),notes:String(d.notes||'').trim().slice(0,500),guide:'Not matched yet',guideId:null,tripId:free?null:(state.activeTripId||'trip-legacy'),tripTitle:free?region+' · '+tripLength(days.length):example?signupText('sampleDay'):state.title,language:d.language||'English',stops:JSON.parse(JSON.stringify(stops)),must:free||example?[]:state.must.filter(id=>stops.some(p=>p.id===id)),createdAt:Date.now()};
 if(state.booking){state.bookingHistory=state.bookingHistory||[];state.bookingHistory.push(JSON.parse(JSON.stringify(state.booking)));}state.quote=null;state.proposals=[];state.booking=null;state.review=null;state.messages=[];state.rating=0;save();return {route:'requested'};
}
function request(){
 const next=activeMateStep();if(next)return empty('You have an ongoing trip.','Review your request or booking status first.',next.route,next.label);
 const params=new URLSearchParams(location.hash.split('?')[1]||''),free=params.get('mode')==='free',example=params.get('sample')==='1',tripId=params.get('trip');
 if(!free&&!example){
  ensureDays();stashDay();stashTrip();
  if(!tripId)return `${title('1 / 2','Choose a trip to share','Choose a trip, then write your request.')}<div class="my-trip-list">${state.trips.map(t=>tripListCard(t,true)).join('')}</div>`;
  if(!state.trips.some(t=>t.id===tripId))return empty('Trip not found.','Please select your trip again.','request','Choose another trip');
  if(state.activeTripId!==tripId)selectTrip(tripId);
 }
 const days=free?[]:itineraryRequestDays(example);
 if(!free&&!days.some(d=>d.stops.length))return empty('Create your trip first','Then you can request a mate','trips','Create my trip');
 return `${!free&&!example?title('2 / 2','Write your request','Review your selected trip and tell mates what help you need.'):''}${free?'':`<section class="handoff card pad"><span class="badge">${days.length===1?'Day trip':tripLength(days.length)}</span><h2>${esc(example?signupText('sampleDay'):state.title)}</h2>${days.map((d,i)=>`<div class="handoff-day"><p class="handoff-date">${days.length>1?`Day ${i+1} · `:''}<time datetime="${esc(d.date)}">${esc(d.date.replaceAll('-','.'))}</time></p><p class="handoff-stops">${d.stops.map(p=>esc(p.name)).join(' → ')||'Ask your mate to suggest a route.'}</p></div>`).join('')}${example?'':`<div class="buttons">${btn('Choose another trip','request','secondary small')}${btn('Edit trip',tripDetailRoute(),'secondary small')}</div>`}</section>`}<p class="request-intro request-intro-outside">${free?'Choose a destination and trip length. Mates will propose a route.':'Share the places in your daily itinerary with mates.'}</p><form id="request-form" class="card pad" data-request-type="${free?'free':'itinerary'}">${!free&&!example?`<input type="hidden" name="tripId" value="${esc(tripId)}">`: ''}${free?`<label>Destination<select name="region" required><option value="" disabled selected>Select your destination.</option>${mateCities.map(city=>`<option value="${esc(city)}">${esc(city)}</option>`).join('')}</select></label><div class="formrow request-date-row"><label>Start date<input type="date" name="date" required value="${future()}"></label><label>Trip length<select name="dayCount">${[1,2,3,4,5,6,7].map(n=>`<option value="${n}">${tripLength(n)}</option>`).join('')}</select></label></div><label>First-day meeting time (Korea)<input type="time" name="time" required value="10:00"></label><p class="hint">Nights describe the trip length. Accommodation and 24-hour accompaniment are not included.</p>`:''}<div class="formrow"><label>Guests<input name="party" type="text" inputmode="numeric" pattern="[0-9]{1,2}" maxlength="2" required value="${esc(state.party)}"></label><label>Tour language<select name="language"><option>English</option></select></label></div><label>Activities or help needed (optional)<textarea name="notes" maxlength="500" placeholder="e.g. Food, shopping, ordering in Korean, must-visit places"></textarea></label><p class="notice">Shared details: dates, area, group size, stops and requests. Draft trips and saved places stay private. Do not include contact details or an exact accommodation address in your requests.</p><label class="check"><input type="checkbox" name="guideAck" required>I agree to share my trip requirements and requests with all approved mates.</label><label class="check"><input type="checkbox" name="ack" required>I will review the proposed route and total price before selecting a mate.</label><p class="hint">Request at least 48 hours before departure. Sending a request does not book or charge you.</p><p id="request-error" class="error" role="alert"></p><button type="submit" class="btn">Find a travel mate</button></form>`;
}

function requested(){const r=state.request;if(!r)return empty('No mate requests yet.','My trips으로 Proposals을 받아보세요.','request','Find a travel mate');const b=state.booking?.requestId===r.id&&['awaiting_mate_fee','confirmed','completed'].includes(state.booking.status)?state.booking:null;const selected=q=>!!b&&(b.proposalId?q.id===b.proposalId:q.guideId===b.guideId&&q.version===b.quoteVersion);const list=proposals().slice().sort((a,c)=>Number(selected(c))-Number(selected(a)));return `${rematchNotice()}${title('',b?'Mate selected':'Received proposals',b?'Review your selected mate and booking status.':'Compare itineraries, inclusions and the total price.')}<section class="card pad request-summary-card"><span class="badge">${esc(r.status==='requested'?'Awaiting proposals':statusLabel(r.status))}</span><h2>${esc(r.tripTitle||state.title)}</h2><p>${requestPeriod(r)} · ${r.party} ${r.party===1?"guest":"guests"} · ${r.requestType==='free'?'자유 견적':(r.stops||[]).length+' places'}</p>${b?`<p><span class="badge rt-status-primary">Selected mate</span> <strong>${esc(b.guide)} Mates</strong></p><p class="hint">${b.status==='awaiting_mate_fee'?'Your booking is confirmed once the mate pays the matching fee.':statusLabel(b.status)}</p>`:''}${state.booking||r.status==='booked'?btn('View booking','booking'):['requested','quoted'].includes(r.status)?action('Stop receiving proposals','withdraw','secondary small'):btn('Find a travel mate','request')}</section>${list.length?`<div class="proposal-section-heading"><h2>Mate proposals</h2><span>${list.length}</span></div><div class="proposal-grid">${list.map(q=>`<article class="card pad proposal-card rt-card-compact">${b?`<span class="badge ${selected(q)?'rt-status-primary':''}">${selected(q)?'Selected mate':'Not selected'}</span>`:''}<a class="guide proposal-header rt-profile-link" href="#guide?proposal=${encodeURIComponent(q.id)}" aria-label="${esc(q.guide)} · View profile"><span class="portrait">${esc(q.guide[0])}</span><div><h2>${esc(q.guide)}${q.guide==='Not matched yet'?'':' Mates'}</h2><p>View profile</p></div>${icon('chevronRight',20)}</a><p class="proposal-description">${esc(q.reason)}</p>${q.message?`<p class="proposal-description"><strong>Message from your mate</strong><br>${esc(q.message).replace(/\n/g,'<br>')}</p>`:''}<strong class="proposal-price">${money(q.amount)}<small> / ${q.party} ${q.party===1?"guest":"guests"} All</small></strong><p class="hint proposal-validity">${b?(selected(q)?statusLabel(b.status):'Proposal not selected'):!['requested','quoted'].includes(r.status)&&!state.booking?'Expired or withdrawn proposal':q.expires>Date.now()?'Proposal available':'Expired'}</p>${selected(q)?btn('View booking','booking'):action('View plan & proposal','select-proposal','secondary',`data-id="${esc(q.id)}"`)}</article>`).join('')}</div>`:`<div class="empty"><h2>${['requested','quoted'].includes(r.status)?'Waiting for mate proposals':'This request is closed'}</h2><p>${['requested','quoted'].includes(r.status)?'Mates will review your trip and send their plans and proposals.':'No proposals arrived for this request. You can create a new travel request.'}</p></div>`}`;}

function quoteValid(){const q=state.quote,r=state.request;return !!(q&&r&&Date.parse(q.date+'T'+(q.time||'00:00')+':00+09:00')>Date.now()&&q.expires>Date.now()&&r.status==='quoted'&&!state.booking&&(!q.requestId||q.requestId===r.id)&&proposals().some(p=>p.id===q.id&&p.version===q.version&&p.amount===q.amount));}
function proposalMessage(q){return q.message?`<section class="card pad quote-section"><h2>Message from your mate</h2><p>${esc(q.message).replace(/\n/g,'<br>')}</p></section>`:'';}
function quote(){const q=state.quote;if(!q)return empty('No proposal yet.','Your itinerary and proposal will appear here once your mate has reviewed your request.','requested','View request');const valid=quoteValid();return `${title('','Your mate proposal','')}${journeySummary(q,'Cash payable in person')}${proposalMessage(q)}<section class="card pad quote-section"><h2>Your proposed itinerary</h2>${journeyPlan(q.plan)}</section><div class="bottomaction journey-action"><p>${state.booking?'Reviewed proposal':valid?'Total for your group · '+money(q.amount):'This proposal has ended'}</p>${state.booking?btn('View booked itinerary','booking'):valid?btn('Select mate & request booking','checkout'):btn(signupText('compareOffers'),'requested','secondary')}</div>`;}

function requestBooking(name,email){if(window.ReelAccess.isAdmin||window.ReelAccess.mode()!=='customer'||state.booking||!quoteValid())return false;const q=state.quote;delete state.request.rematchReason;state.booking={...JSON.parse(JSON.stringify(q)),requestId:state.request.id,proposalId:q.id,id:'RT-DEMO-'+Date.now(),quoteVersion:q.version,status:'awaiting_mate_fee',customer:name,email,requestedAt:Date.now(),feeDeadline:Math.min(Date.now()+24*3600000,Date.parse(q.date+'T'+q.time+':00+09:00')),paymentMethod:'cash',feeRate:.1,feeAmount:Math.round(q.amount*.1),feeStatus:'pending',cashStatus:'uncollected',policyVersion:'CASH-MATCH-10-V1'};syncConversations();state.request.status='matching';state.request.guide=q.guide;state.request.guideId=q.guideId;save();return true;}
function confirmMateFee(outcome){expireMateFee();const b=state.booking;if(window.ReelAccess.isAdmin||window.ReelAccess.mode()!=='guide'||!b||b.status!=='awaiting_mate_fee'||b.feeStatus==='paid')return false;if(outcome!=='success'){b.feeStatus='failed';save();return false;}b.feeStatus='paid';b.feePaidAt=Date.now();b.status='confirmed';b.confirmedAt=Date.now();state.request.status='booked';save();return true;}
function cashNotice(amount){return `<section class="card pad cash-notice"><span class="badge">Cash payment in person</span><h2>Bring cash on your trip day</h2><strong>${money(amount)}</strong><p>Pay your mate directly in cash. Reeltrip connects you and does not collect the trip fee.</p></section>`;}
// Demo grace period; production expiry and payment verification must run on the server.
function feeDeadline(b){return b.feeDeadline||Math.min((b.requestedAt||Date.now())+24*3600000,Date.parse(b.date+'T'+(b.time||'00:00')+':00+09:00'));}
function deadlineNotice(b){return `<div class="notice"><strong>Pay by · ${esc(new Date(feeDeadline(b)).toLocaleString(document.documentElement.lang==='en'?'en-GB':'ko-KR',{timeZone:'Asia/Seoul',month:'long',day:'numeric',hour:'numeric',minute:'2-digit'}))}</strong><br>Korea Standard Time<br>After the deadline, the selection is released and proposals reopen if the trip has not started.</div>`;}
function expireMateFee(){const b=state.booking;if(!b||b.status!=='awaiting_mate_fee')return false;if(!b.feeDeadline)b.feeDeadline=feeDeadline(b);if(Date.now()<b.feeDeadline)return false;releaseMateSelection('expired','Confirmation deadline expired');return true;}
function releaseMateSelection(reason,detail){const b=state.booking;if(!b||b.status!=='awaiting_mate_fee')return false;b.status='cancelled';b.feeStatus='void';b.cancelReason=detail;if(state.request){state.request.status='withdrawn';state.request.rematchReason=reason;}syncConversations();if(!resumeMatching())save();return true;}
function resumeMatching(){const b=state.booking,r=state.request;if(!b||b.status!=='cancelled'||b.feeStatus!=='void'||!r||r.id!==b.requestId||!(Date.parse(r.date+'T'+(r.time||'00:00')+':00+09:00')>Date.now()))return false;syncConversations();state.bookingHistory=state.bookingHistory||[];state.bookingHistory.push(JSON.parse(JSON.stringify(b)));state.proposals=proposals().map(q=>q.id===b.proposalId||q.guideId===b.guideId?{...q,expires:Math.min(q.expires,Date.now())}:q);state.booking=null;state.quote=null;r.status=proposals().some(q=>q.expires>Date.now())?'quoted':'requested';delete r.guide;delete r.guideId;save();return true;}
function reopenMatching(){if(window.ReelAccess.isAdmin||window.ReelAccess.mode()!=='customer')return false;return resumeMatching();}
function rematchNotice(){const r=state.request;if(!r?.rematchReason)return '';const message=r.rematchReason==='expired'?'The mate’s confirmation deadline has passed.':'The mate is unable to proceed.';return `<div class="notice" role="status">${message}<br>${['requested','quoted'].includes(r.status)?'Your trip is receiving proposals again. You can choose another valid proposal now.':'Your trip start time has passed. Change your dates and submit a new request.'}</div>`;}
function feeBreakdown(b){return `<div class="summaryrow"><span>Agreed trip price</span><b>${money(b.amount)}</b></div><div class="summaryrow"><span>10% matching fee</span><b>${money(b.feeAmount)}</b></div>`;}
function refundNotice(b){return `<p class="notice">Fee refund: ${b.refundStatus==='review'?'Under review':'Not applicable'}<br>Cancel booking와 Matching fee 반환은 별도로 처리해요. </p>`;}
function guideFee(){const b=state.booking;if(!b)return empty('No booking has been selected.','You can pay the fee after a traveler selects you.','guide-activity','My activity');const pending=b.status==='awaiting_mate_fee';return `${title('',pending?'Matching fee':'Booking details',pending?'You’ve been selected!':statusLabel(b.status))}<section class="card pad quote-section">${pending?`<div class="mate-fee-amount"><span>Matching fee payable to Reeltrip</span><strong>${money(b.feeAmount)}</strong></div>`:''}${pending?'':`<h2>Booking price</h2>${feeBreakdown(b)}`}${pending?deadlineNotice(b):''}${pending?`<form id="mate-fee-form">${b.feeStatus==='failed'?`<p role="status">${signupText('feeRetry')}</p>`:''}<label class="check"><input type="checkbox" name="terms" required>I understand the 10% matching fee and direct cash payment.</label><label class="developer-only">Payment outcome<select name="outcome"><option value="success">Payment success</option><option value="failure">Payment failed</option></select></label><p id="mate-fee-error" class="error" role="alert"></p><p class="hint">Selecting Pay & confirm booking charges the fee shown above.</p><div class="rt-card-actions rt-card-actions-equal">${btn('Unable to proceed','guide-activity?decline=1','secondary')}<button type="submit" class="btn">Pay & confirm booking</button></div></form><details class="mate-fee-details"><summary>Booking price</summary>${feeBreakdown(b)}</details>`:''}${refundNotice(b)}</section>${mateRequestSummary(b)}<section class="card pad quote-section"><h2>Booked itinerary</h2>${journeyPlan(b.plan)}<p>Confirm the meeting point, daily times and when cash will be paid in chat.</p>${btn('Chat with traveler','chat','secondary')}</section>${mateTripActions(b)}`;}
function mateTripActions(b){
 if(!['confirmed','completed'].includes(b.status))return '';
 const cashPending=b.cashStatus!=='collected';
 const canComplete=b.status==='confirmed'&&Date.now()>=Date.parse((b.endDate||b.date)+'T'+(b.time||'00:00')+':00+09:00')+4*3600000;
 if(!cashPending&&!canComplete&&b.status!=='confirmed')return '';
 return `<section class="card pad quote-section"><h2>Manage your trip</h2>${!cashPending?'<p>Cash received</p>':''}${cashPending||canComplete?`<div class="${cashPending&&canComplete?'rt-card-actions rt-card-actions-equal':'rt-booking-actions'}">${cashPending?action('Confirm cash collection','mate-cash',canComplete?'secondary':''):''}${canComplete?action('Confirm trip completion','mate-complete'):''}</div>`:''}${b.status==='confirmed'?`<div class="rt-booking-actions">${btn('Cancel booking','guide-activity?cancel=1','secondary')}</div>`:''}</section>`;
}
function mateStatusChip(status){const entry=({available:['available','Open for proposals'],waiting:['waiting','Awaiting traveler selection'],awaiting_mate_fee:['selected','Fee payment pending'],confirmed:['confirmed','Confirmed'],completed:['completed','Trip completed'],expired:['expired','Expired'],not_selected:['expired','Not selected'],cancelled:['cancelled','Cancelled']})[status];return `<span class="badge${entry?' rt-status-'+entry[0]:''}">${esc(entry?entry[1]:statusLabel(status))}</span>`;}
function mateFeeActions(b){const active=b===state.booking;return `<div class="rt-card-actions rt-card-actions-equal">${active?btn('Unable to proceed','guide-activity?decline=1','secondary'):'<button class="btn secondary" disabled>Unable to proceed</button>'}${active?btn('Review fee & pay','guide-fee'):'<button class="btn" disabled>Review fee & pay</button>'}</div>${active?'':'<p class="hint">Sample bookings can only be viewed.</p>'}`;}
function mateBookingCard(b){const pending=b.status==='awaiting_mate_fee';return `<section class="card pad quote-section rt-booking-card">${mateStatusChip(b.status)}<h2>${esc(b.tripTitle||b.region||'Travel with a mate')}</h2><p>${requestPeriod(b)} · ${esc(b.customer)}</p>${pending?`<div class="summaryrow"><span>Matching fee (10%)</span><strong>${money(b.feeAmount)}</strong></div><p class="hint">Your booking is confirmed after payment.</p>${deadlineNotice(b)}`:''}${pending?mateFeeActions(b):''}${!pending||b!==state.booking?`<div class="rt-booking-actions">${btn(b.status==='completed'?'View trip history':'View booking',b===state.booking?'guide-fee':'guide-activity?record='+encodeURIComponent(b.id))}</div>`:''}</section>`;}
function mateProposalStatus(q){return q.activityStatus||(state.booking?.requestId===q.requestId&&state.booking.guideId!==q.guideId?'not_selected':q.expires>Date.now()?'waiting':'expired');}
function mateActivityBookings(){const rank={awaiting_mate_fee:0,confirmed:1,completed:2,cancelled:2};return [state.booking,...(state.bookingHistory||[])].filter(b=>b&&b.guideId==='mina').sort((a,b)=>(rank[a.status]??2)-(rank[b.status]??2)||(a.status==='awaiting_mate_fee'?feeDeadline(a)-feeDeadline(b):a.status==='confirmed'?Date.parse(a.date+'T'+(a.time||'00:00'))-Date.parse(b.date+'T'+(b.time||'00:00')):Date.parse(b.endDate||b.date)-Date.parse(a.endDate||a.date))||String(a.id).localeCompare(String(b.id)));}
function guideActivity(){
 const b=state.booking?.guideId==='mina'?state.booking:null,bookings=mateActivityBookings(),sent=proposals().filter(q=>q.guideId==='mina'&&!bookings.some(item=>item.requestId===q.requestId&&item.guideId===q.guideId&&item.quoteVersion===q.version)).sort((a,b)=>Number(mateProposalStatus(a)!=='waiting')-Number(mateProposalStatus(b)!=='waiting')||(mateProposalStatus(a)==='waiting'?a.expires-b.expires:b.expires-a.expires)||String(a.id).localeCompare(String(b.id))),params=new URLSearchParams(location.hash.split('?')[1]||'');
 const tab=params.has('decline')||params.has('cancel')?'bookings':['sent','bookings'].includes(params.get('tab'))?params.get('tab'):bookings.length?'bookings':'sent';
 const record=params.get('record'),proposal=params.get('proposal'),detail=record?bookings.find(x=>x.id===record):proposal?sent.find(x=>x.id===proposal):null;
 if(detail)return `${title('',detail.tripTitle||detail.region||'Trip details')}<section class="card pad quote-section rt-booking-card">${mateStatusChip(record?detail.status:mateProposalStatus(detail))}<h2>${requestPeriod(detail)}</h2><p>${esc(detail.customer||detail.guide)} · ${detail.party} guests</p>${feeBreakdown({...detail,feeAmount:detail.feeAmount??Math.round(detail.amount*.1)})}${record&&detail.status==='awaiting_mate_fee'?deadlineNotice(detail)+mateFeeActions(detail):''}${detail.cancelReason?`<p>${esc(detail.cancelReason)}</p>`:''}</section><section class="card pad quote-section"><h2>Booked itinerary</h2>${journeyPlan(detail.plan)}</section>${btn('Back to My activity','guide-activity?tab='+(record?'bookings':'sent'),'secondary')}`;
 const cancellation=b&&((params.has('decline')&&b.status==='awaiting_mate_fee')||(params.has('cancel')&&b.status==='confirmed'));
 return `<nav class="rt-segmented-tabs" aria-label="Activity categories">${[['sent','Sent proposal',sent.length],['bookings','Bookings',bookings.length]].map(([key,label,count])=>`<a href="#guide-activity?tab=${key}" ${tab===key?'aria-current="page"':''}>${label}<span class="badge">${count}</span></a>`).join('')}</nav><div class="rt-card-stack">${cancellation?`<form id="mate-cancel-form" class="card pad"><h2>${b.status==='awaiting_mate_fee'?'Unable to proceed':'Cancel booking'}</h2><label>Reason<textarea name="reason" required minlength="2" maxlength="500"></textarea></label><p>Before confirmation, the selection is released and proposals automatically reopen if the trip has not started. After confirmation, the booking is cancelled immediately. Matching fee 반환은 별도로 검토해요.</p><div class="rt-card-actions rt-card-actions-equal">${btn('Go back','guide-fee','secondary')}<button class="btn" type="submit">${b.status==='awaiting_mate_fee'?'Decline booking':'Cancel booking'}</button></div></form>`:''}${tab==='bookings'?[[ 'awaiting_mate_fee','Needs confirmation'],['confirmed','Upcoming trips'],['history','Completed and cancelled trips']].map(([status,label])=>{const rows=bookings.filter(x=>status==='history'?['completed','cancelled'].includes(x.status):x.status===status);return rows.length?`${bookings.length>1?`<h2>${label} <span class="badge">${rows.length}</span></h2><p class="hint">${status==='awaiting_mate_fee'?'Payment deadline: soonest first':status==='confirmed'?'Trip date: soonest first':'Trip date: newest first'}</p>`:''}${rows.map(mateBookingCard).join('')}`:'';}).join(''):''}${tab==='sent'&&sent.length?`${sent.length>1?'<p class="hint">Awaiting response first · Expiring soonest first · Closed proposals newest first</p>':''}${sent.map(q=>`<article class="card pad quote-section rt-booking-card">${mateStatusChip(mateProposalStatus(q))}<h2>${esc(q.tripTitle||q.region||'Travel with a mate')} · ${q.party} ${q.party===1?"guest":"guests"}</h2><p>${requestPeriod(q)}</p><p>${money(q.amount)}</p>${btn('View sent proposal',q.requestId===state.request?.id?'guide-quote':'guide-activity?proposal='+encodeURIComponent(q.id),'secondary')}</article>`).join('')}`:''}${(tab==='sent'?!sent.length:!bookings.length)?`<section class="card pad rt-empty-card"><span class="rt-empty-card-icon" aria-hidden="true">${icon('trips',28)}</span><h2>${tab==='sent'?'No proposals sent yet.':'No bookings yet.'}</h2><p>${tab==='sent'?'Find a trip you would like to join and send a proposal.':'Bookings appear here when a traveler selects your proposal.'}</p><div class="rt-card-actions">${btn('Find trips','guide-desk')}</div></section>`:''}</div>`;
}

function checkout(){if(state.booking)return empty('This proposal already has a booking request.','Open the booking to check its current status.','booking','Open booking');if(!quoteValid())return empty(state.quote&&state.quote.expires<=Date.now()?'This proposal has expired.':'Check a trip proposal before booking.','Review your mate’s proposal again before booking.','quote','View proposal');const q=state.quote;return `${title('','Select mate & request booking','Your booking is confirmed once the mate pays the matching fee.')}${journeySummary(q,'Cash payable in person')}<form id="checkout-form" class="card pad quote-section"><h2>Traveler details</h2><label>Your name<input name="name" required maxlength="60" placeholder="Please enter your name." value="${esc(state.profile?.nickname||'')}" autocomplete="name"></label><label>Email<span class="rt-field">${icon('mail')}<input name="email" type="email" required placeholder="Please enter your email." autocomplete="email"></span></label><label class="check"><input name="terms" type="checkbox" required>I agree to the itinerary and total price and will pay my mate in cash on the trip day.</label><label class="check"><input name="pendingAck" type="checkbox" required>I understand this is a booking request, confirmed only after the mate pays the matching fee.</label><p id="checkout-error" class="error" role="alert"></p><button type="submit" class="btn">Select mate & request booking</button></form>`;}

function booking(){const b=state.booking;if(!b&&state.request?.rematchReason)return requested();if(!b)return empty('No bookings yet.','Mates의  days정과 가격을 Confirm한 뒤 Bookings을 요청하세요.','requested','View request');const pending=b.status==='awaiting_mate_fee',confirmed=['confirmed','completed'].includes(b.status);return `${title('Your guided trip',pending?'Waiting for your mate to confirm':statusLabel(b.status),'')}${pending?'<div class="notice">Your booking is pending until your mate pays the matching fee.</div>':''}${journeySummary(b,'Cash payable in person')}${confirmed?'<p class="notice">Pay your mate directly in cash on the day of your trip.</p>':''}${confirmed?`<section class="meeting-card"><span class="badge">Where to meet</span><h2>Arrange your meeting point with your mate</h2><p>${requestPeriod(b)} · First day ${b.time} / Korea time (KST)</p><p class="hint">Confirm your first meeting point and daily mate hours in chat.</p></section>`:''}<section class="card pad quote-section"><h2>${pending?'Requested itinerary':'Booked itinerary'}</h2>${journeyPlan(b.plan)}</section>${['awaiting_mate_fee','confirmed'].includes(b.status)?`<div class="rt-booking-actions">${btn(signupText('backTrips'),'trips')}${btn(pending?'Withdraw booking request':'Cancel booking','cancel','secondary')}</div>`:''}${confirmed?(syncConversations().some(room=>conversationBooking(room)&&conversationOpen(room))?`<div class="bottomaction journey-action">${btn('Message your mate','chat')}</div>`:'<p class="notice">You can chat once your mate sends the first message.</p>'):''}${b.status==='cancelled'&&b.feeStatus==='void'?`<section class="card pad"><p>${esc(b.cancelReason||'')}</p>${state.request?.rematchReason?rematchNotice()+btn('Change dates and request again','request','secondary'):action('Choose another mate proposal','reopen-matching','secondary')}</section>`:''}${b.refundStatus==='review'?refundNotice(b):''}`;}

// Conversation IDs are stable across proposal revisions and booking confirmation.
function conversationKey(requestId,guideId){return JSON.stringify([requestId,guideId]);}
function ensureConversation(q,requestId=state.request?.id){
 if(!requestId||!q)return null;
 if(!Array.isArray(state.conversations))state.conversations=[];
 const guideId=q.guideId||'mina',id=conversationKey(requestId,guideId);
 let room=state.conversations.find(c=>c.id===id);
 if(!room){room={id,requestId,guideId,guide:q.guide,tripTitle:q.tripTitle||state.request?.tripTitle||state.title,endDate:q.endDate||q.date,date:q.date,customer:state.profile?.nickname||'Traveler',messages:[],read:{customer:0,guide:0},createdAt:Date.now()};state.conversations.push(room);}
 return room;
}
function syncConversations(){
 if(isGuest())return [];
 if(!Array.isArray(state.conversations))state.conversations=[];
 const b=state.booking;
 if(b){
  const requestId=b.requestId||state.request?.id||b.id;
  const room=ensureConversation(b,requestId);
  if(room){
   room.bookingId=b.id;room.customer=b.customer||room.customer;room.status=b.status;room.date=b.date;room.endDate=b.endDate||b.date;room.mutualConsent=true;
   // Keep the old storage field compatible, importing its history only once.
   if(!room.legacyImported){if(!room.messages.length&&state.messages?.length)room.messages=state.messages.map(m=>({...m,sender:m.sender||'customer'}));room.legacyImported=true;}
  }
 }
 return state.conversations;
}
function conversationBooking(room){const b=state.booking;return b&&conversationKey(b.requestId||state.request?.id||b.id,b.guideId||'mina')===room.id?b:null;}
function conversationEndsAt(room){
 const b=conversationBooking(room)||room;
 const end=b.endDate||b.date;
 return end?Date.parse(end+'T00:00:00+09:00')+86400000:NaN;
}
// Browser-local safety MVP. Replace local participant IDs with authenticated server IDs at integration.
const reportReasons={spam:'Spam or advertising',abuse:'Abuse or harassment',fraud:'Fraud or money requests',unsafe:'Inappropriate behavior',other:'Other'};
function safetyRecords(){if(!Array.isArray(state.userBlocks))state.userBlocks=[];if(!Array.isArray(state.userReports))state.userReports=[];}
function safetyPair(room){return {customer:room.customerId||'customer:local',guide:'guide:'+room.guideId};}
function safetyActor(room){return safetyPair(room)[window.ReelAccess.mode()];}
function safetyTarget(room){const pair=safetyPair(room);return window.ReelAccess.mode()==='guide'?pair.customer:pair.guide;}
function safetyName(room){return window.ReelAccess.mode()==='guide'?(room.customer||'Traveler'):(room.guide||'Mates');}
function ownBlock(room){safetyRecords();return state.userBlocks.find(b=>b.actor===safetyActor(room)&&b.target===safetyTarget(room));}
function conversationBlocked(room){safetyRecords();const p=safetyPair(room);return state.userBlocks.some(b=>(b.actor===p.customer&&b.target===p.guide)||(b.actor===p.guide&&b.target===p.customer));}
function safetyAllowed(room){return !isGuest()&&!window.ReelAccess.isAdmin&&!!room&&syncConversations().includes(room)&&!!safetyActor(room);}
function setUserBlock(room,blocked){
 if(!safetyAllowed(room))return false;safetyRecords();
 const existing=ownBlock(room);if(blocked&&!existing)state.userBlocks.push({actor:safetyActor(room),target:safetyTarget(room),name:safetyName(room),actorName:window.ReelAccess.mode()==='guide'?room.guide:room.customer,actorRole:window.ReelAccess.mode(),at:Date.now()});
 if(!blocked)state.userBlocks=state.userBlocks.filter(b=>b!==existing);save();return true;
}
function reportUser(room,reason,details){
 if(!safetyAllowed(room)||!Object.hasOwn(reportReasons,reason))return false;
 details=String(details||'').trim();if(details.length>1000||(reason==='other'&&!details))return false;safetyRecords();
 if(state.userReports.some(r=>r.actor===safetyActor(room)&&r.threadId===room.id))return false;
 state.userReports.push({id:'report-'+Date.now(),actor:safetyActor(room),target:safetyTarget(room),threadId:room.id,actorName:window.ReelAccess.mode()==='guide'?room.guide:room.customer,targetName:safetyName(room),actorRole:window.ReelAccess.mode(),reason,details,at:Date.now(),status:'local'});save();return true;
}
function safetyMenu(){const room=chatContext()?.room;if(!safetyAllowed(room))return;
 modal(`<h2>Report or block</h2><p>${esc(safetyName(room))}</p><div class="rt-action-menu-list"><button type="button" class="rt-action-menu-item" data-action="user-report">${icon('warning')}<span>Report user</span></button><button type="button" class="rt-action-menu-item rt-action-menu-item--danger" data-action="user-block">${icon('lock')}<span>${ownBlock(room)?'Unblock':'Block user'}</span></button></div><div class="buttons">${action('Close','close')}</div>`);
}
function unblockNotice(){return 'After unblocking, you can exchange messages in eligible conversations. Messaging stays unavailable if the other person has blocked you or the conversation has ended. Reports are kept.';}
function blockedUsers(){safetyRecords();const mode=window.ReelAccess.mode(),actors=new Set(syncConversations().map(safetyActor));const blocks=state.userBlocks.filter(b=>actors.has(b.actor)&&(mode==='guide'?b.actor.startsWith('guide:'):!b.actor.startsWith('guide:')));
 modal(`<h2>Blocked users${blocks.length?` <span class="badge">${blocks.length}</span>`:''}</h2>${blocks.length?`<p>Blocking stops messages with this person in every conversation. Existing conversations and bookings are kept. Bookings must be cancelled separately.</p><div class="rt-card-stack">${blocks.slice().sort((a,b)=>b.at-a.at).map(b=>`<section class="card pad"><div class="sectionhead"><h3>${esc(b.name)}</h3><span class="badge">Blocked</span></div><div class="rt-card-actions">${action('Unblock','user-unblock','secondary small',`data-id="${esc(b.target)}" data-actor="${esc(b.actor)}"`)}</div></section>`).join('')}</div>`:`<section class="card pad rt-empty-card"><span class="rt-empty-card-icon" aria-hidden="true">${icon('lock')}</span><h3>No blocked users.</h3><p>You can block someone from the menu at the top right of a conversation. View and unblock them here.</p></section>`}<div class="buttons">${action('Close','close','secondary')}</div>`);
}
function conversationOpen(room){
 if(conversationBlocked(room))return false;
 const b=conversationBooking(room);
 return !!b&&b.feeStatus==='paid'&&room.mutualConsent===true&&['confirmed','completed'].includes(b.status)&&Date.now()<conversationEndsAt(room)&&(window.ReelAccess.mode()==='guide'||room.messages.some(m=>m.sender==='guide'));
}
function conversationStatus(room){if(conversationBlocked(room))return 'Blocked conversation';const b=conversationBooking(room);if(b?.status==='awaiting_mate_fee')return 'Awaiting mate payment';if(b?.feeStatus==='paid'&&['confirmed','completed'].includes(b.status)&&Date.now()<conversationEndsAt(room)&&!room.messages.some(m=>m.sender==='guide'))return 'Awaiting the first message from your mate';return conversationOpen(room)?'Chat open':room.mutualConsent?'Closed conversation':'Awaiting mutual agreement';}
function chatPolicyButton(){return `<button type="button" class="chat-policy-button" data-action="chat-policy" aria-label="About chat" title="About chat" aria-haspopup="dialog" aria-controls="dialog">${icon('info')}</button>`; }
function chatPolicy(){return `<h2 id="chat-policy-title">About chat</h2><ul class="chat-policy-list"><li>Travelers can join the chat after their mate pays the fee and sends the first message.</li><li>You can chat until midnight at the end of your last travel day (Korea time). After that, chat is read-only.</li><li>Chat closes when a booking is withdrawn or cancelled.</li><li>You can send text only, up to 1,000 characters per message.</li><li>Use chat to confirm where and when to meet. Chat does not change your booked itinerary or price.</li><li>Your booking is confirmed after the mate pays the 10% fee. Chat is unavailable before payment.</li></ul><div class="chat-policy-footer"><button type="button" class="btn secondary" data-action="close">Close</button></div>`;}
function conversationRoute(room){return 'chat?thread='+encodeURIComponent(room.id);}
function conversationUnread(room){if(!conversationOpen(room))return 0;const mode=window.ReelAccess.mode();return room.messages.slice(room.read?.[mode]||0).filter(m=>(m.sender||'customer')!==mode).length;}
function unreadChats(){return isGuest()?0:syncConversations().reduce((sum,room)=>sum+conversationUnread(room),0);}
function chatContext(){
 const params=new URLSearchParams(location.hash.split('?')[1]||''),rooms=syncConversations();
 if(!isGuest()&&params.has('thread')){const room=rooms.find(c=>c.id===params.get('thread'));return room?{sample:false,room,booking:conversationBooking(room)||room,messages:room.messages}:null;}
 if(!isGuest()&&params.get('sample')!=='1'&&state.booking){const room=rooms.find(c=>conversationBooking(c));if(room)return {sample:false,room,booking:state.booking,messages:room.messages};}
 return null;
}
function markChatRead(){
 if(isGuest()||window.ReelAccess.isAdmin||current()!=='chat')return;
 const context=chatContext();if(!context||context.sample)return;
 const room=context.room,mode=window.ReelAccess.mode();room.read=room.read||{};
 if(room.read[mode]!==room.messages.length){room.read[mode]=room.messages.length;save();}
}
function sendChatMessage(value){
 if(isGuest()||window.ReelAccess.isAdmin)return false;
 const text=String(value||'').trim(),context=chatContext();
 if(!text||text.length>1000||!context||!conversationOpen(context.room))return false;
 const list=context.messages;
 list.push({text,sender:window.ReelAccess.mode(),at:Date.now()});
 if(!context.sample&&conversationBooking(context.room))state.messages=context.messages;
 save();return true;
}
function chatTime(at){if(!Number.isFinite(at))return '';return new Intl.DateTimeFormat(signupLanguage(),{timeZone:'Asia/Seoul',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(at);}
function conversationCard(room){
 const b=conversationBooking(room)||room,last=room.messages.at(-1),guideMode=window.ReelAccess.mode()==='guide',unread=conversationUnread(room),name=guideMode?(b.customer||'Traveler'):room.guide;
 return `<a class="conversation-item card pad ${!conversationOpen(room)?'is-closed':unread?'is-unread':''}" href="#${esc(conversationRoute(room))}"><span class="conversation-avatar" aria-hidden="true">${esc(Array.from(name||'?')[0])}</span><div><div class="conversation-heading"><h2>${esc(name)}</h2>${last?.at?`<time datetime="${new Date(last.at).toISOString()}">${esc(chatTime(last.at))}</time>`:''}</div><p class="conversation-preview">${last&&(last.sender||'customer')===window.ReelAccess.mode()?'You: ':''}${esc(last?.text||'Discuss your itinerary and meeting point.')}</p><p class="conversation-trip">${esc(room.tripTitle)}</p><div class="conversation-meta"><span>${requestPeriod(room)}</span>${conversationOpen(room)?'':`<span class="conversation-status">${conversationStatus(room)}</span>`}</div></div>${unread?`<span class="chat-unread" aria-label="${unread} unread messages">${unread}</span>`:`<span class="conversation-chevron" aria-hidden="true">${icon('chevronRight')}</span>`}</a>`;
}
function messages(){
 const rooms=syncConversations().filter(room=>room.messages.length||(conversationBooking(room)?.feeStatus==='paid'&&window.ReelAccess.mode()==='guide')).slice().sort((a,b)=>Number(conversationOpen(b))-Number(conversationOpen(a))||(b.messages.at(-1)?.at||b.createdAt)-(a.messages.at(-1)?.at||a.createdAt));
 const guideMode=window.ReelAccess.mode()==='guide';
 const blank=`<section class="card chat-empty rt-empty-card"><span class="conversation-avatar" aria-hidden="true">${icon('messages')}</span><h2>No conversations yet.</h2><p>${guideMode?'Confirm the booking by paying the fee, then send the traveler the first message.':'Chat starts when your mate sends the first message after booking confirmation.'}</p>${btn(guideMode?'View open trips':state.request?'Received proposals':'Explore mates',guideMode?'guide-desk':state.request?'requested':'guides','small')}</section>`;
 return `<div class="conversation-list">${rooms.length?rooms.map(conversationCard).join(''):blank}</div>`;
}
function chatDate(at){return Number.isFinite(at)?new Intl.DateTimeFormat(signupLanguage(),{timeZone:'Asia/Seoul',year:'numeric',month:'long',day:'numeric'}).format(at):'';}
function chatClock(at){return Number.isFinite(at)?new Intl.DateTimeFormat(signupLanguage(),{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false}).format(at):'';}
function chat(){
 const context=chatContext();if(!context)return messages();
 const b=context.booking,guideMode=window.ReelAccess.mode()==='guide',mode=window.ReelAccess.mode(),room=context.room,open=conversationOpen(room),booked=conversationBooking(room),name=guideMode?(b.customer||'Traveler'):(room.guide||b.guide||'Mates');
 const detail=`<section class="chat-trip-context"><div><span class="chat-context-label">Your trip together</span><strong>${esc(room.tripTitle)}</strong><p>${requestPeriod(room)}${booked?' · '+statusLabel(b.status):''}</p></div>${booked?btn('Booking details',guideMode?'guide-fee':'booking','secondary small'):room.requestId===state.request?.id?btn('View proposal',guideMode?'guide-desk':'requested','secondary small'):''}</section>`;
 let previousDate='';
 const history=context.messages.map((m,i)=>{
  const mine=(m.sender||'customer')===mode,date=chatDate(m.at),separator=date&&date!==previousDate?`<div class="chat-date"><span>${esc(date)}</span></div>`:'';previousDate=date;
  const read=mine&&(room.read?.[guideMode?'customer':'guide']||0)>i;
  return `${separator}<div class="chat-message ${mine?'is-mine':'is-peer'}"><span class="chat-sender">${mine?'Me':esc(name)}</span><div class="bubble ${mine?'mine':''}">${esc(m.text)}</div><div class="chat-message-meta">${Number.isFinite(m.at)?`<time datetime="${new Date(m.at).toISOString()}">${esc(chatClock(m.at))}</time>`:''}${read?'<span>Read</span>':''}</div></div>`;
 }).join('');
 const composer=open?`<form id="chat-form" class="chat-composer"><textarea name="text" rows="1" aria-label="Message" maxlength="1000" required placeholder="Type a message"></textarea><button type="submit" class="btn rt-round-action" aria-label="Send message">${icon('send')}</button></form>`:`<p class="chat-closed" role="status">${conversationBlocked(room)?'Messaging is unavailable because of a block.':b.status==='awaiting_mate_fee'?'Chat is available after your mate pays the fee.':b.feeStatus==='paid'&&Date.now()<conversationEndsAt(room)&&['confirmed','completed'].includes(b.status)&&!room.messages.some(m=>m.sender==='guide')?'You can chat once your mate sends the first message.':'This conversation is closed. You can still view its history.'}</p>`;
 return `<div class="chat-room"><header class="chat-person"><a class="app-back" href="#messages" aria-label="Go back">${icon('chevronLeft')}</a><span class="conversation-avatar" aria-hidden="true">${esc(Array.from(name)[0])}</span><div><h1>${esc(name)}</h1></div>${action(icon('more'),'user-safety','secondary rt-round-action','aria-label="Report or block" aria-haspopup="dialog"')}</header><div class="chat-surface">${detail}<p class="chat-system-note">Chat does not change your itinerary or price. Use it to confirm the meeting point.</p><div class="chat" id="chat-log" role="log" aria-live="polite" aria-label="Conversation" tabindex="0">${history||`<div class="chat-start"><span aria-hidden="true">${icon('messages')}</span><strong>${open?'Say hello':'No messages yet'}</strong><p>${open?'Discuss where and when to meet here.':'Messages will appear here when the conversation starts.'}</p></div>`}</div><div class="chat-compose-area">${composer}</div></div></div>`;
}

