function publicRequestMatch(r){
 const regions=mateApplication().fields?.regions||[];
 const area=[r.region,...(r.stops||[]).map(p=>[p.area,p.address].filter(Boolean).join(' '))].filter(Boolean).join(' ').toLowerCase();
 const cityAliases=['서울 Seoul','부산 Busan','대구 Daegu','인천 Incheon','광주 Gwangju','대전 Daejeon','울산 Ulsan','세종 Sejong','경기 Gyeonggi','강원 Gangwon','충북 Chungbuk','충남 Chungnam','전북 Jeonbuk','전남 Jeonnam','경북 Gyeongbuk','경남 Gyeongnam','제주 Jeju'];
 const region=regions.some(v=>{const names=v.district==='all'?(cityAliases[v.city]||'').split(' '):[mateDistrictsFor(v.city)[v.district]];return names.some(name=>name&&area.includes(name.toLowerCase()));});
 return {region,available:requestAvailable(r)};
}
function publicTravelRequests(requests=state.request?[state.request]:[]){
 return requests.filter(r=>r&&['requested','quoted'].includes(r.status)&&(!r.visibility||r.visibility==='approved_mates')&&state.booking?.requestId!==r.id)
 .sort((a,b)=>{const x=publicRequestMatch(a),y=publicRequestMatch(b);return Number(y.region&&y.available)-Number(x.region&&x.available)||Number(y.available)-Number(x.available)||Number(y.region)-Number(x.region)||(b.createdAt||0)-(a.createdAt||0)||String(a.id).localeCompare(String(b.id));});
}
function guideDesk(){const rows=publicTravelRequests(),b=state.booking,activeBooking=b?.guideId==='mina'&&['awaiting_mate_fee','confirmed'].includes(b.status)?b:null;return `<div class="pagehead"><div><p class="muted">Requests matching your area and available dates appear first. You can also browse requests in other areas.</p></div></div>${activeBooking?mateBookingCard(activeBooking):''}${rows.length?rows.map(r=>{
 const match=publicRequestMatch(r);
 const sent=proposals().some(q=>q.guideId==='mina'&&q.expires>Date.now()&&(!q.requestId||q.requestId===r.id));
 const region=String(r.region||'').trim()||[...new Set((r.stops||[]).map(p=>String(p.area||'').trim()).filter(Boolean))].join(', ');
 return `<section class="card pad rt-request-card"><div class="rt-request-badges">${mateStatusChip(sent?'waiting':'available')}${match.region&&match.available?'<span class="badge">Area and dates match</span>':''}</div><h2>${requestPeriod(r)}</h2>${region?`<p class="rt-request-region">${icon('location',18)}<span>${esc(region)}</span></p>`:''}<dl class="rt-request-facts"><div><dt>Start time</dt><dd>${esc(r.time||'—')}</dd></div><div><dt>Travelers</dt><dd>${esc(r.party)} guests</dd></div><div><dt>Language</dt><dd>${esc(r.language||'English')}</dd></div></dl>${!match.available?'<p class="hint">These dates overlap with a confirmed booking. Please check other requests.</p>':''}<div class="rt-card-actions">${btn(sent?'View sent proposal':'View trip & propose','guide-quote')}</div></section>`;
 }).join(''):empty('No new requests.','Trips appear here when travelers request proposals.','guide-activity','My activity')}`;}


let quoteMapRequest='',quoteMapDay=0;
function updateQuoteMap(day=null,focus=null){
 const form=$('#quote-form'),draft=form?{amount:form.elements.amount?.value,plan:form.elements.plan?.value,ack:form.elements.ack?.checked}:null;
 if(day!==null)quoteMapDay=day;if(focus!==null)state.focus=focus;
 render();
 const next=$('#quote-form');if(next&&draft){for(const key of ['amount','plan'])if(next.elements[key]&&draft[key]!==undefined)next.elements[key].value=draft[key];if(next.elements.ack)next.elements.ack.checked=draft.ack;}
}
function requestItineraryMap(r){
 if(r.requestType==='free')return journeyPlan(r.plan||requestPlan(r));
 const key=r.requestId||r.id||'';if(quoteMapRequest!==key){quoteMapRequest=key;quoteMapDay=0;}
 const days=r.days?.length?r.days:[{date:r.date,time:r.time,stops:r.stops||[]}];
 if(!days.some(d=>d.stops?.length))return journeyPlan(r.plan||requestPlan(r));
 quoteMapDay=Math.min(Math.max(0,quoteMapDay),days.length-1);
 const day=days[quoteMapDay],stops=day.stops||[];
 const tabs=days.length>1?`<div class="day-tabs" aria-label="Travel date">${days.map((d,i)=>`<button type="button" data-action="quote-map-day" data-value="${i}" aria-pressed="${quoteMapDay===i}" class="${quoteMapDay===i?'active':''}">Day ${i+1}<small>${esc(d.date||'')}</small></button>`).join('')}</div>`:'';
 const map=stops.length?mapPanel([],stops).replaceAll('data-action="focus-place"','type="button" data-action="quote-map-focus"'):'';
 return `${tabs}${map}<div class="sectionhead"><h3>${quoteMapDay+1} day · ${esc(day.date||'')}</h3></div>${stops.length?`<ol class="trip-timeline">${stops.map((p,i)=>`<li class="trip-timeline-stop"><span class="trip-stop-number">${i+1}</span><div class="trip-stop-content"><span><strong>${esc(p.name)}</strong><small>${esc(p.address||p.area||'')}</small></span><span class="trip-stop-photo">${placeArt(p)}</span></div>${i<stops.length-1?travelLeg(p,stops[i+1]):''}</li>`).join('')}</ol>`:'<p class="hint">No places are listed for this day.</p>'}`;
}
function guideQuote(){const r=state.request;if(state.booking){const b=state.booking;if(b.guideId!=='mina')return side('guide',empty('The traveler selected another mate’s proposal.','Find another trip and send a proposal.','guide-desk','Find trips'));const pending=b.status==='awaiting_mate_fee';if(pending)return side('guide',`${title('','The traveler selected your proposal!')}${mateBookingCard(b)}`);return side('guide',empty(pending?'The traveler selected your proposal!':'View your selected booking.',pending?'Pay the 10% matching fee to confirm the booking.':'View your booking status and trip details directly.','guide-fee',pending?'Review fee & pay':'View booking'));}if(!r||!['requested','quoted'].includes(r.status))return side('guide',empty('No request available to proposal.','Check its status in your inbox.','guide-desk','Requests'));const sent=proposals().find(q=>q.guideId==='mina'&&q.expires>Date.now());if(sent)return side('guide',`${title('','Sent proposal','Sent proposals cannot be edited. Please wait for the traveler to choose.')}${mateRequestSummary(sent)}${proposalMessage(sent)}<section class="card pad quote-section"><h2>Trip itinerary</h2>${requestItineraryMap(sent)}</section>`);return side('guide',`${title('','Send a trip proposal','Review the request and enter the total price for the group.')}${mateRequestSummary(r)}<form id="quote-form" class="card pad quote-section">${r.requestType==='free'?`<label>Itinerary for each day<textarea name="plan" required minlength="10" maxlength="2000" placeholder="Enter the places to visit each day."></textarea></label>`:`<h2>Trip itinerary</h2>${requestItineraryMap(r)}`}<label>Total trip price for the group (KRW)<input type="number" name="amount" min="0" step="1" required placeholder="e.g. 240000"></label><label>Write a message for the traveler!<textarea name="message" maxlength="1000" rows="4" placeholder="Write a message for the traveler!"></textarea></label><p class="hint">Your message appears in the traveler’s received proposals and proposal details.</p><p class="notice">If selected, pay 10% of the total to confirm. Your amount after the fee is 90% of the price, before other expenses.</p><p class="hint">Meals, shopping, transport and admission are extra. Sent proposals are valid for 24 hours and cannot be edited.</p><label class="check"><input name="ack" type="checkbox" required>I have checked the requested itinerary and total price.</label><p id="quote-error" class="error" role="alert"></p><button class="btn" type="submit">Send a trip proposal</button></form>`);}

function requestAvailable(r=state.request){
 if(!r)return false;
 const start=r.date,end=r.endDate||r.date;
 return [state.booking,...(state.bookingHistory||[])].filter(b=>b&&['confirmed'].includes(b.status)).every(b=>end<b.date||start>(b.endDate||b.date));
}
