function makeQuote(amount,plan,reason,pricing,sender='mina',message=''){const r=state.request;if(!r||!['requested','quoted'].includes(r.status)||state.booking)return false;if(!requestAvailable()){toast('Your mate is unavailable on this date. Choose another date.');return false;}if(amount===undefined)amount=240000*(r.dayCount||1);if(!Number.isSafeInteger(amount)||amount<0||!['mina','jun'].includes(sender))return false;const existing=proposals().find(q=>q.guideId===sender);if(existing?.expires>Date.now())return false;plan=r.requestType==='free'?String(plan||'').trim():requestPlan(r);if(r.requestType==='free'&&(plan.length<10||plan.length>2000))return false;message=String(message||'').trim();if(message.length>1000)return false;state.quote={message,requestId:r.id,guideId:sender,pricingPolicyVersion:"2026-11-23-mvp",feeRate:.1,feeVatIncluded:null,pricing:{hours:4*(r.dayCount||1)},id:'QT-'+r.id+'-'+sender,version:(existing?.version||0)+1,guide:sender==='jun'?'Jun':'Mina',requestType:r.requestType||'itinerary',tripTitle:r.tripTitle,region:r.region,endDate:r.endDate||r.date,dayCount:r.dayCount||1,days:JSON.parse(JSON.stringify(r.days||[])),date:r.date,time:r.time,party:r.party,amount,plan:plan||requestPlan(r),reason:r.requestType==='free'?'An itinerary for your requested dates and group.':'Join the trip with your requested itinerary unchanged.',expires:Date.now()+86400000};state.proposals=[...proposals().filter(q=>q.guideId!==sender),state.quote];state.request.status='quoted';save();return true;}
